import std.collection.ArrayList

class Student <: Equatable<Student>{

    /*
    This is a class representing a student with basic information and course scores.
    It implements Equatable<Student> to support comparison between two Student instances.
    */

    let name: String
    let grade: Int64
    let major: String
    let cources: HashMap<String, Int64>

    public init(name: String, grade: Int64, major: String) {
        /*
        Initialize a Student instance.
        :param name: String, the name of the student
        :param grade: Int64, the grade/year of the student
        :param major: String, the major of the student
        */

        this.name = name
        this.grade = grade
        this.major = major
        this.cources = HashMap<String, Int64>()
    }

    public override operator func != (that: Student): Bool {
        /*
        Check if two Student instances are NOT equal.
        Two students are considered not equal if any of their fields differ.
        :param that: Another Student object to compare with
        :return: Bool, true if any field differs; otherwise false
        */

        var flag = false
        if (this.name != that.name) {
            flag = true
        }
        if (this.grade != that.grade) {
            flag = true
        }
        if (this.major != that.major) {
            flag = true
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                flag = true
            } else {
                if (v != that.cources[k]) {
                    flag = true
                }
            }
        }
        return flag
    }

    public override operator func == (that: Student): Bool {
        /*
        Check if two Student instances are equal.
        Two students are equal only if all their fields (name, grade, major, and course scores) match exactly.
        :param that: Another Student object to compare with
        :return: Bool, true if all fields match; otherwise false
        */

        if (this.name != that.name) {
            return false
        }
        if (this.grade != that.grade) {
            return false
        }
        if (this.major != that.major) {
            return false
        }
        for ((k, v) in this.cources) {
            if (!that.cources.contains(k)) {
                return false
            }
            if (v != that.cources[k]) {
                return false
            }
        }
        return true
    }
}

class AssessmentSystem {

    /*
    This is a class as an student assessment system, which supports add student, add course score, calculate GPA, and other functions for students and courses.
    */

    let students: HashMap<String, Student>

    public init() {
        /*
        Initialize the students dict in assessment system.
        */
        this.students = HashMap<String, Student>()
    }

    public func add_student(name: String, grade: Int64, major: String): Unit {
        /*
        Add a new student into this.students dict
        :param name: String, student name
        :param grade: Int64, student grade
        :param major: String, student major
        >>> system.add_student('student 1', 3, 'SE')
        >>> system.students
        {'student 1': Student('student 1', 3, 'SE')}
        */

        let student = Student(name, grade, major)
        this.students[name] = student
    }

    public func add_course_score(name: String, course: String, score: Int64): Unit {
        /*
        Add score of specific course for student in this.students
        :param name: String, student name
        :param course: String, cource name
        :param score: Int64, cource score
        >>> system.add_student('student 1', 3, 'SE')
        >>> system.add_course_score('student 1', 'math', 94)
        >>> system.students
        {'student 1': Student('student 1', 3, 'SE', {'math': 94})}
        */

        if (this.students.contains(name)) {
            let student = this.students[name]
            student.cources[course] = score
        }
    }

    public func get_gpa(name: String): Option<Float64> {
        /*
        Get average grade of one student.
        :param name: String, student name
        :return: if name is in students and this students have courses grade, return average grade(Float64)
                    or None otherwise
        >>> system.add_student('student 1', 3, 'SE')
        >>> system.add_course_score('student 1', 'math', 94)
        >>> system.add_course_score('student 1', 'Computer Network', 92)
        >>> system.get_gpa('student 1')
        93.0

        */

        if (!this.students.contains(name)) {
            return None
        }

        let student = this.students[name]
        if (student.cources.size == 0) {
            return None
        }

        var total: Float64 = 0.0
        for ((k, v) in student.cources) {
            total = total + (v as Float64)
        }

        let gpa = total / (student.cources.size as Float64)
        return Some(gpa)
    }

    public func get_all_students_with_fail_course(): ArrayList<String> {
        /*
        Get all students who have any score blow 60
        :return: list of String ,student name
        >>> system.add_course_score('student 1', 'Society', 59)
        >>> system.get_all_students_with_fail_course()
        ['student 1']
        */

        let result = ArrayList<String>()
        for ((name, student) in this.students) {
            for ((course, score) in student.cources) {
                if (score < 60) {
                    result.add(name)
                    break
                }
            }
        }
        return result
    }

    public func get_course_average(course: String): Option<Float64> {
        /*
        Get the average score of a specific course.
        :param course: String, course name
        :return: Float64, average scores of this course if anyone have score of this course, or None if nobody have records.
        Tip: If someone do not have the score of this course, the score is -1.
        */

        var total: Float64 = 0.0
        var count: Int64 = 0
        for ((name, student) in this.students) {
            if (student.cources.contains(course)) {
                total = total + (student.cources[course] as Float64)
                count = count + 1
            }
        }

        if (count == 0) {
            return None
        }

        let average = total / (count as Float64)
        return Some(average)
    }

    public func get_top_student(): Option<String> {
        /*
        Calculate every student's gpa with get_gpa method, and find the student with highest gpa
        :return: String, name of student whose gpa is highest
        >>> system.add_student('student 1', 3, 'SE')
        >>> system.add_student('student 2', 2, 'SE')
        >>> system.add_course_score('student 1', 'Computer Network', 92)
        >>> system.add_course_score('student 2', 'Computer Network', 97)
        >>> system.get_top_student()
        'student 2'
        */

        var top_student: Option<String> = None
        var highest_gpa: Option<Float64> = None

        for ((name, student) in this.students) {
            let gpa = this.get_gpa(name)
            if (gpa.isSome()) {
                if (highest_gpa.isNone()) {
                    highest_gpa = gpa
                    top_student = Some(name)
                } else if (gpa.getOrThrow() > highest_gpa.getOrThrow()) {
                    highest_gpa = gpa
                    top_student = Some(name)
                }
            }
        }

        return top_student
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.unicode.UnicodeStringExtension

class AutomaticGuitarSimulator {

    /*
    This class is an automatic guitar simulator that can interpret and play based on the input guitar sheet music.
    */

    let play_text: String

    public init(text: String) {
        /*
        Initialize the score to be played
        :param text:String, score to be played
        */
        this.play_text = text
    }

    public func interpret(display!: Bool = false): ArrayList<HashMap<String, String>> {
        /*
        Interpret the music score to be played
        :param display:Bool, representing whether to print the interpreted score
        :return: list of HashMap, The HashMap includes two fields, Chord and Tune, which are letters and numbers, respectively. If the input is empty or contains only whitespace, an empty list is returned.
        >>> context = AutomaticGuitarSimulator("C53231323 Em43231323 F43231323 G63231323")
        >>> play_list = context.interpret(display: false)
        [{'Chord': 'C', 'Tune': '53231323'}, {'Chord': 'Em', 'Tune': '43231323'}, {'Chord': 'F', 'Tune': '43231323'}, {'Chord': 'G', 'Tune': '63231323'}]

        */

        let result: ArrayList<HashMap<String, String>> = ArrayList<HashMap<String, String>>()

        if play_text.isEmpty() || play_text.trim().isEmpty() {
            return result
        }

        let parts: [String] = play_text.split(" ")

        for part in parts {
            if !part.isEmpty() {
                var chord: String = ""
                var tune: String = ""

                var i: Int = 0
                // Extract chord (letters and possibly 'm' for minor chords)
                while i < part.length() {
                    let char: Char = part.charAt(i)
                    if char.isDigit() {
                        break
                    }
                    chord = chord + String([char])
                    i = i + 1
                }

                // Extract tune (numbers)
                while i < part.length() {
                    let char: Char = part.charAt(i)
                    if !char.isDigit() {
                        break
                    }
                    tune = tune + String([char])
                    i = i + 1
                }

                let entry: HashMap<String, String> = HashMap<String, String>()
                entry.insert("Chord", chord)
                entry.insert("Tune", tune)

                result.add(entry)

                if display {
                    this.display(key: chord, value: tune)
                }
            }
        }

        return result
    }

    public func display(key: String, value: String): String {
        /*
        Print out chord and play tune with following format: Normal Guitar Playing -- Chord: %s, Play Tune: %s
        :param key:String, chord
        :param value:String, play tune
        :return: String
        >>> context = AutomaticGuitarSimulator("C53231323 Em43231323 F43231323 G63231323")
        >>> context.display("C", "53231323")
        Normal Guitar Playing -- Chord: C, Play Tune: 53231323

        */
        let output: String = "Normal Guitar Playing -- Chord: " + key + ", Play Tune: " + value
        print(output)
        return output
    }
}

import std.collection.ArrayList

class AvgPartition {

    /*
    This is a class that partitions the given list into different blocks by specifying the number of partitions, with each block having a uniformly distributed length.
    */

    let lst: ArrayList<Int64>
    let limit: Int64

    public init(lst: ArrayList<Int64>, limit: Int64) {
        /*
        Initialize the class with the given list and the number of partitions, and check if the number of partitions is greater than 0.
        */
        this.lst = lst
        this.limit = limit
    }

    public func setNum(): (Int64, Int64) {
        /*
        Calculate the size of each block and the remainder of the division.
        :return: the size of each block and the remainder of the division, tuple.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.setNum()
        (2, 0)

        */
        let size = this.lst.size() / this.limit
        let remainder = this.lst.size() % this.limit
        return (size, remainder)
    }

    public func get(index: Int64): ArrayList<Int64> {
        /*
        calculate the size of each block and the remainder of the division, and calculate the corresponding start and end positions based on the index of the partition.
        :param index: the index of the partition, Int64.
        :return: the corresponding block, ArrayList<Int64>.
        >>> a = AvgPartition(ArrayList<Int64>([1, 2, 3, 4]), 2)
        >>> a.get(0)
        [1, 2]

        */
        let (size, remainder) = this.setNum()
        let start = index * size + (if (index < remainder) index else remainder)
        let end = (index + 1) * size + (if (index + 1 < remainder) index + 1 else remainder)

        let result = ArrayList<Int64>()
        var i = start
        while (i < end && i < this.lst.size()) {
            result.add(this.lst.get(i).getOrThrow())
            i++
        }
        return result
    }
}

import std.collection.ArrayList

class BalancedBrackets {

    /*
    This is a class that checks for bracket matching
    */

    let stack: ArrayList<String>
    let left_brackets: ArrayList<String>
    let right_brackets: ArrayList<String>
    var expr: String

    public init(expr: String) {
        /*
        Initializes the class with an expression.
        :param expr: The expression to check for balanced brackets,String.
        */
        this.stack = ArrayList<String>()
        this.left_brackets = ArrayList<String>(["(", "{", "["])
        this.right_brackets = ArrayList<String>([")", "}", "]"])
        this.expr = expr
    }

    public func clear_expr(): Unit {
        /*
        Clears the expression of all characters that are not brackets.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.clear_expr()
        >>> b.expr
        '()'

        */
        var result: String = ""
        var i: Int64 = 0
        while (i < this.expr.length()) {
            let ch: String = this.expr.charAt(i).toString()
            if (this.is_bracket(ch)) {
                result = result + ch
            }
            i = i + 1
        }
        this.expr = result
    }

    private func is_bracket(ch: String): Bool {
        var i: Int64 = 0
        while (i < this.left_brackets.size()) {
            if (this.left_brackets.get(i).getOrThrow() == ch) {
                return true
            }
            i = i + 1
        }
        i = 0
        while (i < this.right_brackets.size()) {
            if (this.right_brackets.get(i).getOrThrow() == ch) {
                return true
            }
            i = i + 1
        }
        return false
    }

    public func check_balanced_brackets(): Bool {
        /*
        Checks if the expression has balanced brackets.
        :return: true if the expression has balanced brackets, false otherwise.
        >>> b = BalancedBrackets("a(b)c")
        >>> b.check_balanced_brackets()
        true

        */
        this.stack.clear()
        var i: Int64 = 0
        while (i < this.expr.length()) {
            let ch: String = this.expr.charAt(i).toString()
            if (this.left_brackets.contains(ch)) {
                this.stack.add(ch)
            } else if (this.right_brackets.contains(ch)) {
                if (this.stack.isEmpty()) {
                    return false
                }
                let last: String = this.stack.pop().getOrThrow()
                if (!this.is_matching_pair(last, ch)) {
                    return false
                }
            }
            i = i + 1
        }
        return this.stack.isEmpty()
    }

    private func is_matching_pair(left: String, right: String): Bool {
        if (left == "(" && right == ")") {
            return true
        }
        if (left == "{" && right == "}") {
            return true
        }
        if (left == "[" && right == "]") {
            return true
        }
        return false
    }
}

class BankAccount {

    /*
    This is a class as a bank account system, which supports deposit money, withdraw money, view balance, and transfer money.
    */

    var balance: Int64

    public init(balance!: Int64 = 0) {
        /*
        Initializes a bank account object with an attribute balance, default value is 0.
        */
        this.balance = balance
    }

    public func deposit(amount: Int64): Int64 {
        /*
        Deposits a certain amount into the account, increasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        :param amount: Int64
        */
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        this.balance = this.balance + amount
        return this.balance
    }

    public func withdraw(amount: Int64): Int64 {
        /*
        Withdraws a certain amount from the account, decreasing the account balance, return the current account balance.
        If amount is negative, throw Exception("Invalid amount").
        If the withdrawal amount is greater than the account balance, throw Exception("Insufficient balance.").
        :param amount: Int64
        */
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        if (amount > this.balance) {
            throw Exception("Insufficient balance.")
        }
        this.balance = this.balance - amount
        return this.balance
    }

    public func view_balance(): Int64 {
        /*
        Return the account balance.
        */
        return this.balance
    }

    public func transfer(other_account: BankAccount, amount: Int64): Unit {
        /*
        Transfers a certain amount from the current account to another account.
        :param other_account: BankAccount
        :param amount: Int64
        >>> account1 = BankAccount()
        >>> account2 = BankAccount()
        >>> account1.deposit(1000)
        >>> account1.transfer(account2, 300)
        account1.balance = 700 account2.balance = 300
        */
        if (amount < 0) {
            throw Exception("Invalid amount")
        }
        if (amount > this.balance) {
            throw Exception("Insufficient balance.")
        }
        this.balance = this.balance - amount
        other_account.balance = other_account.balance + amount
    }
}

import std.convert.Parsable

class BigNumCalculator {

    /*
    This is a class that implements big number calculations, including adding, subtracting and multiplying.
    */

    public static func add(num1: String, num2: String): String {
        /*
        Adds two big numbers.
        :param num1: The first number to add,String.
        :param num2: The second number to add,String.
        :return: The sum of the two numbers,String.
        >>> BigNumCalculator.add("12345678901234567890", "98765432109876543210")
        '111111111011111111100'

        */
        if (num1 == "0") return num2
        if (num2 == "0") return num1

        var isNegative1 = false
        var isNegative2 = false
        var n1 = num1
        var n2 = num2

        if (num1[0] == '-') {
            isNegative1 = true
            n1 = num1.slice(1, num1.length)
        }
        if (num2[0] == '-') {
            isNegative2 = true
            n2 = num2.slice(1, num2.length)
        }

        if (isNegative1 && isNegative2) {
            // Both negative: add absolute values and make result negative
            var result = addStrings(n1, n2)
            return "-" + result
        } else if (isNegative1) {
            // First negative, second positive: subtract
            return subtractStrings(n2, n1)
        } else if (isNegative2) {
            // First positive, second negative: subtract
            return subtractStrings(n1, n2)
        } else {
            // Both positive: add
            return addStrings(n1, n2)
        }
    }

    private static func addStrings(num1: String, num2: String): String {
        var result: [Int32] = []
        var carry = 0
        var i = num1.length - 1
        var j = num2.length - 1

        while (i >= 0 || j >= 0 || carry > 0) {
            var digit1 = if (i >= 0) num1[i] - '0' else 0
            var digit2 = if (j >= 0) num2[j] - '0' else 0

            var sum = digit1 + digit2 + carry
            result.append(sum % 10)
            carry = sum / 10

            i = i - 1
            j = j - 1
        }

        var resultStr = ""
        for (k in result.length - 1 .. -1) {
            resultStr = resultStr + String.fromInt(result[k])
        }
        return resultStr
    }

    private static func subtractStrings(num1: String, num2: String): String {
        if (num1 == num2) return "0"

        var isNegative = false
        var n1 = num1
        var n2 = num2

        // Compare absolute values to determine which is larger
        if (isSmaller(n1, n2)) {
            // num2 is larger than num1, so result will be negative
            var temp = n1
            n1 = n2
            n2 = temp
            isNegative = true
        }

        var result: [Int32] = []
        var borrow = 0
        var i = n1.length - 1
        var j = n2.length - 1

        while (i >= 0) {
            var sub = (n1[i] - '0') - borrow
            if (j >= 0) {
                sub = sub - (n2[j] - '0')
            }

            if (sub < 0) {
                sub = sub + 10
                borrow = 1
            } else {
                borrow = 0
            }

            result.append(sub)
            i = i - 1
            j = j - 1
        }

        // Remove leading zeros
        var resultStr = ""
        var isLeadingZero = true
        for (k in result.length - 1 .. -1) {
            if (result[k] != 0) isLeadingZero = false
            if (!isLeadingZero) {
                resultStr = resultStr + String.fromInt(result[k])
            }
        }

        if (resultStr == "") resultStr = "0"

        if (isNegative && resultStr != "0") {
            resultStr = "-" + resultStr
        }

        return resultStr
    }

    private static func isSmaller(num1: String, num2: String): Bool {
        if (num1.length != num2.length) {
            return num1.length < num2.length
        }
        for (i in 0 .. num1.length) {
            if (num1[i] != num2[i]) {
                return num1[i] < num2[i]
            }
        }
        return false
    }

    public static func subtract(num1: String, num2: String): String {
        /*
        Subtracts two big numbers.
        :param num1: The first number to subtract,String.
        :param num2: The second number to subtract,String.
        :return: The difference of the two numbers,String.
        >>> BigNumCalculator.subtract("12345678901234567890", "98765432109876543210")
        '-86419753208641975320'

        */
        if (num2 == "0") return num1
        if (num1 == "0") {
            if (num2[0] == '-') {
                return num2.slice(1, num2.length)
            } else {
                return "-" + num2
            }
        }

        var isNegative1 = false
        var isNegative2 = false
        var n1 = num1
        var n2 = num2

        if (num1[0] == '-') {
            isNegative1 = true
            n1 = num1.slice(1, num1.length)
        }
        if (num2[0] == '-') {
            isNegative2 = true
            n2 = num2.slice(1, num2.length)
        }

        if (isNegative1 && isNegative2) {
            // Both negative: (-a) - (-b) = b - a
            return subtractStrings(n2, n1)
        } else if (isNegative1) {
            // First negative, second positive: (-a) - b = -(a + b)
            var result = addStrings(n1, n2)
            return "-" + result
        } else if (isNegative2) {
            // First positive, second negative: a - (-b) = a + b
            return addStrings(n1, n2)
        } else {
            // Both positive: a - b
            return subtractStrings(n1, n2)
        }
    }

    public static func multiply(num1: String, num2: String): String {
        /*
        Multiplies two big numbers.
        :param num1: The first number to multiply,String.
        :param num2: The second number to multiply,String.
        :return: The product of the two numbers,String.
        >>> BigNumCalculator.multiply("12345678901234567890", "98765432109876543210")
        '1219326311370217952237463801111263526900'

        */
        if (num1 == "0" || num2 == "0") return "0"

        var isNegative1 = false
        var isNegative2 = false
        var n1 = num1
        var n2 = num2

        if (num1[0] == '-') {
            isNegative1 = true
            n1 = num1.slice(1, num1.length)
        }
        if (num2[0] == '-') {
            isNegative2 = true
            n2 = num2.slice(1, num2.length)
        }

        var isResultNegative = isNegative1 != isNegative2

        var result = multiplyStrings(n1, n2)

        if (isResultNegative && result != "0") {
            return "-" + result
        } else {
            return result
        }
    }

    private static func multiplyStrings(num1: String, num2: String): String {
        if (num1 == "0" || num2 == "0") return "0"
        if (num1 == "1") return num2
        if (num2 == "1") return num1

        var len1 = num1.length
        var len2 = num2.length

        var result: [Int32] = []
        for (i in 0 .. len1 + len2) {
            result.append(0)
        }

        var i1 = 0
        for (i in len1 - 1 .. -1) {
            var carry = 0
            var n1Digit = num1[i] - '0'
            var i2 = 0

            for (j in len2 - 1 .. -1) {
                var n2Digit = num2[j] - '0'

                var sum = n1Digit * n2Digit + result[i1 + i2] + carry

                carry = sum / 10
                result[i1 + i2] = sum % 10

                i2 = i2 + 1
            }

            if (carry > 0) {
                result[i1 + i2] = result[i1 + i2] + carry
            }

            i1 = i1 + 1
        }

        var resultStr = ""
        var isLeadingZero = true
        for (i in result.length - 1 .. -1) {
            if (result[i] != 0) isLeadingZero = false
            if (!isLeadingZero || i == 0) {
                resultStr = resultStr + String.fromInt(result[i])
            }
        }

        return resultStr
    }
}

import std.collection.HashMap
import std.convert.RadixConvertible

class BinaryDataProcessor {

    /*
    This is a class used to process binary data, which includes functions such as clearing non 0 or 1 characters, counting binary string information, and converting to corresponding strings based on different encoding methods.
    */

    var binary_string: String

    public init(binary_string: String) {
        /*
        Initialize the class with a binary string and clean it by removing all non 0 or 1 characters.
        */
        this.binary_string = binary_string
        this.clean_non_binary_chars()
    }

    public func clean_non_binary_chars(): Unit {
        /*
        Clean the binary string by removing all non 0 or 1 characters.
        >>> bdp = BinaryDataProcessor("01101000daf3e4r01100101011011000110110001101111")
        >>> bdp.clean_non_binary_chars()
        >>> bdp.binary_string
        '0110100001100101011011000110110001101111'

        */
        var cleaned: String = ""
        for (i in 0..this.binary_string.length()) {
            let ch = this.binary_string.get(i)
            if (ch == '0' || ch == '1') {
                cleaned = cleaned + ch
            }
        }
        this.binary_string = cleaned
    }

    public func calculate_binary_info(): HashMap<String, Float64> {
        /*
        Calculate the binary string information, including the percentage of 0 and 1, and the total length of the binary string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.calculate_binary_info()
        {'Zeroes': 0.475, 'Ones': 0.525, 'Bit length': 40.0}

        */
        let total_length = this.binary_string.length()
        if (total_length == 0) {
            var result: HashMap<String, Float64> = HashMap<String, Float64>()
            result.add("Zeroes", 0.0)
            result.add("Ones", 0.0)
            result.add("Bit length", 0.0)
            return result
        }

        var count_0: Int64 = 0
        var count_1: Int64 = 0

        for (i in 0..total_length) {
            let ch = this.binary_string.get(i)
            if (ch == '0') {
                count_0 = count_0 + 1
            } else if (ch == '1') {
                count_1 = count_1 + 1
            }
        }

        let percentage_0 = count_0 as Float64 / total_length as Float64
        let percentage_1 = count_1 as Float64 / total_length as Float64

        var result: HashMap<String, Float64> = HashMap<String, Float64>()
        result.add("Zeroes", percentage_0)
        result.add("Ones", percentage_1)
        result.add("Bit length", total_length as Float64)

        return result
    }

    public func convert_to_ascii(): String {
        /*
        Convert the binary string to ascii string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_ascii()
        'hello'

        */
        var result: String = ""
        let chunk_size = 8

        for (i in 0..this.binary_string.length() step chunk_size) {
            if (i + chunk_size <= this.binary_string.length()) {
                let chunk = this.binary_string.substring(i, i + chunk_size)
                let char_code = this.binary_to_decimal(chunk)
                result = result + char_code as Rune
            }
        }

        return result
    }

    private func binary_to_decimal(binary: String): Int64 {
        var result: Int64 = 0
        var power: Int64 = 0

        for (i in (binary.length() - 1)..-1) {
            let ch = binary.get(i)
            if (ch == '1') {
                result = result + (1 as Int64 << power)
            }
            power = power + 1
        }

        return result
    }

    public func convert_to_utf8(): String {
        /*
        Convert the binary string to utf-8 string.
        >>> bdp = BinaryDataProcessor("0110100001100101011011000110110001101111")
        >>> bdp.convert_to_utf8()
        'hello'

        */
        // For ASCII characters, UTF-8 encoding is the same as ASCII
        // So we can use the same conversion as ASCII
        return this.convert_to_ascii()
    }
}

class BitStatusUtil {

    /*
    This is a utility class that provides methods for manipulating and checking status using bitwise operations.
    */

    public static func add(states: Int64, stat: Int64): Int64 {
        /*
        Add a status to the current status,and check the parameters wheather they are legal.
        :param states: Current status,Int64.
        :param stat: Status to be added,Int64.
        :return: The status after adding the status,Int64.
        >>> BitStatusUtil.add(2,4)
        6

        */
        check([states, stat])
        return states | stat
    }

    public static func has(states: Int64, stat: Int64): Bool {
        /*
        Check if the current status contains the specified status,and check the parameters wheather they are legal.
        :param states: Current status,Int64.
        :param stat: Specified status,Int64.
        :return: true if the current status contains the specified status,otherwise false,Bool.
        >>> BitStatusUtil.has(6,2)
        true

        */
        check([states, stat])
        return (states & stat) == stat
    }

    public static func remove(states: Int64, stat: Int64): Int64 {
        /*
        Remove the specified status from the current status,and check the parameters wheather they are legal.
        :param states: Current status,Int64.
        :param stat: Specified status,Int64.
        :return: The status after removing the specified status,Int64.
        >>> BitStatusUtil.remove(6,2)
        4

        */
        check([states, stat])
        return states & (~stat)
    }

    public static func check(args: Array<Int64>): Unit {
        /*
        Check if the parameters are legal, args must be greater than or equal to 0 and must be even,if not,throw Exception.
        If arg is negative, throw Exception("${arg} must be greater than or equal to 0")
        If arg is not even, throw Exception("${arg} not even")
        :param args: Parameters to be checked,Array<Int64>.
        :return: Unit.
        >>> BitStatusUtil.check([2,3,4])
        Traceback (most recent call last):
        ...
        Exception: 3 not even
        */
        for (arg in args) {
            if (arg < 0) {
                throw Exception("${arg} must be greater than or equal to 0")
            }
            if (arg % 2 != 0) {
                throw Exception("${arg} not even")
            }
        }
    }
}

import std.random.Random
import std.collection.ArrayList
import std.convert.Parsable

class BlackjackGame {

    /*
    This is a class representing a game of blackjack, which includes creating a deck, calculating the value of a hand, and determine the winner based on the hand values of the player and dealer.
    */

    let deck: ArrayList<String>
    let player_hand: ArrayList<String>
    let dealer_hand: ArrayList<String>

    public init() {
        /*
        Initialize the Blackjack Game with the attribute deck, player_hand and dealer_hand.
        While initializing deck attribute, call the create_deck method to generate.
        The deck stores 52 rondom order poker with the Jokers removed, format is ['AS', '2S', ...].
        player_hand is a ArrayList<String> which stores player's hand cards.
        dealer_hand is is a ArrayList<String> which stores dealer's hand cards.
        */
        this.deck = BlackjackGame.create_deck()
        this.player_hand = ArrayList<String>()
        this.dealer_hand = ArrayList<String>()
    }

    public static func shuffle_arraylist(arr: ArrayList<String>): ArrayList<String> {
        /*
        Shuffles the input ArrayList of strings using the Fisher-Yates (Knuth) shuffle algorithm.
        This algorithm produces a uniformly random permutation by swapping each element 
        with a randomly selected element that comes before it (including itself) in the list,
        ensuring each element has an equal probability of being in any position.

        :param arr: The ArrayList of strings to be shuffled
        :return: The shuffled ArrayList of strings (same object as input, shuffled in-place)
        */
        let rnd = Random()
        for (i in (arr.size - 1)..0:-1) {
            let j = rnd.nextInt64(i + 1)  // Fixed: was (i + 2), should be (i + 1)
            //  swap arr[i] and arr[j]
            let temp = arr[i]
            arr[i] = arr[j]
            arr[j] = temp
        }
        return arr
    }

    public static func create_deck(): ArrayList<String> {
        /*
        Create a deck of 52 cards, which stores 52 rondom order poker with the Jokers removed.
        :return: a list of 52 rondom order poker with the Jokers removed, format is ['AS', '2S', ...].()
        >>> BlackjackGame.create_deck()
        ['QD', '9D', 'JC', 'QH', '2S', 'JH', '7D', '6H', '9S', '5C', '7H', 'QS', '5H',
        '6C', '7C', '3D', '10C', 'AD', '4C', '5D', 'AH', '2D', 'QC', 'KH', '9C', '9H',
        '4H', 'JS', '6S', '8H', '8C', '4S', '3H', '10H', '7S', '6D', '3C', 'KC', '3S',
        '2H', '10D', 'KS', '4D', 'AC', '10S', '2C', 'KD', '5S', 'JD', '8S', 'AS', '8D']
        */
        let suits = ArrayList<String>()
        suits.add("S")  // Spades
        suits.add("H")  // Hearts
        suits.add("D")  // Diamonds
        suits.add("C")  // Clubs

        let ranks = ArrayList<String>()
        ranks.add("A")   // Ace
        ranks.add("2")
        ranks.add("3")
        ranks.add("4")
        ranks.add("5")
        ranks.add("6")
        ranks.add("7")
        ranks.add("8")
        ranks.add("9")
        ranks.add("10")
        ranks.add("J")   // Jack
        ranks.add("Q")   // Queen
        ranks.add("K")   // King

        let deck = ArrayList<String>()
        for (suit in suits.iterator()) {
            for (rank in ranks.iterator()) {
                deck.add(rank + suit)
            }
        }

        return BlackjackGame.shuffle_arraylist(deck)
    }

    public func calculate_hand_value(hand: ArrayList<String>): Int64 {
        /*
        Calculate the value of the poker cards stored in hand list according to the rules of the Blackjack Game.
        If the card is a digit, its value is added to the total hand value.
        Value of J, Q, or K is 10, while Aces are worth 11.
        If the total hand value exceeds 21 and there are Aces present, one Ace is treated as having a value of 1 instead of 11,
        until the hand value is less than or equal to 21, or all Aces have been counted as value of 1.
        :param hand: ArrayList<String>
        :return: the value of the poker cards stored in hand list, a number.
        >>> black_jack_game = BlackjackGame()
        >>> black_jack_game.calculate_hand_value(ArrayList<String>(['QD', '9D', 'JC', 'QH', 'AS']))
        40
        */
        var total_value: Int64 = 0
        var ace_count: Int64 = 0

        for (card in hand.iterator()) {
            let rank = card.slice(0, card.size - 1)  // Extract rank (all characters except the last one)

            if (rank == "J" || rank == "Q" || rank == "K") {
                total_value += 10
            } else if (rank == "A") {
                total_value += 11
                ace_count += 1
            } else {
                total_value += rank.parseInt64()  // Parse numeric rank
            }
        }

        // Adjust for Aces if total is over 21
        while (total_value > 21 && ace_count > 0) {
            total_value -= 10  // Convert an Ace from 11 to 1
            ace_count -= 1
        }

        return total_value
    }

    public func check_winner(player_hand: ArrayList<String>, dealer_hand: ArrayList<String>): String {
        /*
        Determines the winner of a game by comparing the hand values of the player and dealer.
        rule:
        If both players have hand values that are equal to or less than 21, the winner is the one whose hand value is closer to 21.
        Otherwise, the winner is the one with the lower hand value.
        :param player_hand: ArrayList<String>
        :param dealer_hand: ArrayList<String>
        :return: the result of the game, only two certain String: 'Dealer wins' or 'Player wins'
        >>> black_jack_game = BlackjackGame()
        >>> black_jack_game.check_winner(ArrayList<String>(['QD', '9D', 'JC', 'QH', 'AS']), ArrayList<String>(['QD', '9D', 'JC', 'QH', '2S']))
        'Player wins'
        */
        let player_value = this.calculate_hand_value(player_hand)
        let dealer_value = this.calculate_hand_value(dealer_hand)

        let player_over = player_value > 21
        let dealer_over = dealer_value > 21

        if (player_over && dealer_over) {
            // Both over 21, lower value wins
            if (player_value < dealer_value) {
                return "Player wins"
            } else {
                return "Dealer wins"
            }
        } else if (player_over) {
            // Only player over 21
            return "Dealer wins"
        } else if (dealer_over) {
            // Only dealer over 21
            return "Player wins"
        } else {
            // Both <= 21, closer to 21 wins
            if (player_value > dealer_value) {
                return "Player wins"
            } else {
                return "Dealer wins"
            }
        }
    }
}

import std.collection.HashMap

class BookManagement {

    /*
    This is a class as managing books system, which supports to add and remove books from the inventory dict, view the inventory, and check the quantity of a specific book.
    */

    let inventory: HashMap<String, Int64>

    public init() {
        /*
        Initialize the inventory of Book Manager.
        */
        this.inventory = HashMap<String, Int64>()
    }

    public func add_book(title: String, quantity!: Int64=1): Unit {
        /*
        Add one or several books to inventory which is sorted by book title.
        :param title: String, the book title
        :param quantity: Int64, default value is 1.
        */
        var currentQuantity: Int64 = 0
        if (this.inventory.contains(title)) {
            currentQuantity = this.inventory.get(title).getOrThrow()
        }
        this.inventory.add(title, currentQuantity + quantity)
    }

    public func remove_book(title: String, quantity: Int64): Unit {
        /*
        Remove one or several books from inventory which is sorted by book title.
        throw Exception("Invalid operation") while get invalid input.
        :param title: String, the book title
        :param quantity: Int64
        */
        if (quantity < 0) {
            throw Exception("Invalid operation")
        }

        if (!this.inventory.contains(title)) {
            throw Exception("Invalid operation")
        }

        var currentQuantity = this.inventory.get(title).getOrThrow()
        if (quantity > currentQuantity) {
            throw Exception("Invalid operation")
        }

        var newQuantity = currentQuantity - quantity
        if (newQuantity == 0) {
            this.inventory.remove(title)
        } else {
            this.inventory.add(title, newQuantity)
        }
    }

    public func view_inventory(): HashMap<String, Int64> {
        /*
        Get the inventory of the Book Management.
        :return this.inventory: HashMap<String, Int64>
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.add_book("book2", quantity: 1)
        >>> bookManagement.view_inventory()
        {'book1': 1, 'book2': 1}
        */
        return this.inventory
    }

    public func view_book_quantity(title: String): Int64 {
        /*
        Get the quantity of a book.
        :param title: String, the title of the book.
        :return quantity: the quantity of this book title. return 0 when the title does not exist in this.inventory
        >>> bookManagement = BookManagement()
        >>> bookManagement.add_book("book1", quantity: 1)
        >>> bookManagement.view_book_quantity("book3")
        0
        */
        if (this.inventory.contains(title)) {
            return this.inventory.get(title).getOrThrow()
        } else {
            return 0
        }
    }
}

import std.collection.ArrayList

class BoyerMooreSearch {

    /*
    his is a class that implements the Boyer-Moore algorithm for string searching, which is used to find occurrences of a pattern within a given text.
    */

    let text: String
    let pattern: String
    let textLen: Int64
    let patLen: Int64

    public init(text: String, pattern: String) {
        /*
        Initializes the BoyerMooreSearch class with the given text and pattern.
        :param text: The text to be searched, String.
        :param pattern: The pattern to be searched for, String.
        */
        this.text = text
        this.pattern = pattern
        this.textLen = text.size
        this.patLen = pattern.size
    }

    public func match_in_pattern(char: String): Int64 {
        /*
        Finds the rightmost occurrence of a character in the pattern.
        :param char: The character to be searched for, String.
        :return: The index of the rightmost occurrence of the character in the pattern, Int64.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
        >>> boyerMooreSearch.match_in_pattern("A")
        0

        */
        if (this.patLen == 0) {
            return -1
        }

        // Loop from the end of the pattern to the beginning to find the rightmost occurrence
        var i: Int64 = this.patLen - 1
        while (i >= 0) {
            if (this.pattern[i] == char[0]) {
                return i
            }
            i = i - 1
        }

        return -1
    }

    public func mismatch_in_text(currentPos: Int64): Int64 {
        /*
        Determines the position of the first dismatch between the pattern and the text.
        :param currentPos: The current position in the text, Int64.
        :return: The position of the first dismatch between the pattern and the text, Int64,otherwise -1.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "ABC")
        >>> boyerMooreSearch.mismatch_in_text(0)
        2

        */
        if (currentPos < 0 || currentPos + this.patLen > this.textLen) {
            return -1
        }

        var i: Int64 = this.patLen - 1
        var j: Int64 = currentPos + this.patLen - 1

        // Compare pattern and text from right to left
        while (i >= 0 && j >= currentPos) {
            if (this.pattern[i] != this.text[j]) {
                return i  // Return the position in the pattern where mismatch occurred
            }
            i = i - 1
            j = j - 1
        }

        return -1  // No mismatch found - pattern matches at this position
    }

    public func bad_character_heuristic(): ArrayList<Int64> {
        /*
        Finds all occurrences of the pattern in the text.
        :return: A list of all positions of the pattern in the text, ArrayList<Int64>.
        >>> boyerMooreSearch = BoyerMooreSearch("ABAABA", "AB")
        >>> boyerMooreSearch.bad_character_heuristic()
        [0, 3]

        */
        let result = ArrayList<Int64>()

        if (this.patLen == 0) {
            return result
        }

        if (this.patLen > this.textLen) {
            return result
        }

        var shift: Int64 = 0

        while (shift <= this.textLen - this.patLen) {
            var j: Int64 = this.patLen - 1

            // Compare pattern and text from right to left
            while (j >= 0 && this.pattern[j] == this.text[shift + j]) {
                j = j - 1
            }

            if (j < 0) {
                // Pattern found at shift
                result.add(shift)

                // Calculate next shift using bad character heuristic
                if (shift + this.patLen < this.textLen) {
                    let badCharShift = this.match_in_pattern(this.text[shift + this.patLen].toString())
                    if (badCharShift == -1) {
                        shift = shift + this.patLen + 1
                    } else {
                        shift = shift + (this.patLen - badCharShift)
                    }
                } else {
                    shift = shift + 1
                }
            } else {
                // Calculate shift based on bad character heuristic
                let badChar = this.text[shift + j].toString()
                let badCharShift = this.match_in_pattern(badChar)

                let newShift: Int64
                if (badCharShift == -1) {
                    newShift = j + 1
                } else {
                    newShift = j - badCharShift
                }

                if (newShift > 0) {
                    shift = shift + newShift
                } else {
                    shift = shift + 1
                }
            }
        }

        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.convert.Parsable

class Calculator {

    /*
    This is a class for a calculator, capable of performing basic arithmetic calculations on numerical expressions using the operators +, -, *, /, and ^ (exponentiation).
    */

    let operators: HashMap<String, (Float64, Float64) -> Float64>

    public init() {
        /*
        Initialize the operations performed by the five operators'+','-','*','/','^'
        */
        this.operators = HashMap<String, (Float64, Float64) -> Float64>()
        operators.add("+", {x: Float64, y: Float64 => x + y})
        operators.add("-", {x: Float64, y: Float64 => x - y})
        operators.add("*", {x: Float64, y: Float64 => x * y})
        operators.add("/", {x: Float64, y: Float64 => x / y})
        operators.add("^", {x: Float64, y: Float64 => x ** y})
    }

    public func calculate(expression: String): Option<Float64> {
        /*
        Calculate the value of a given expression
        :param expression: String, given expression
        :return:If successful, returns the value of the expression; otherwise, returns None
        >>> calculator = Calculator()
        >>> calculator.calculate('1+2-3')
        0.0
        */
        let operand_stack: ArrayList<Float64> = ArrayList<Float64>()
        let operator_stack: ArrayList<String> = ArrayList<String>()

        var i: Int64 = 0
        while (i < expression.length()) {
            let char: String = expression.charAt(i).toString()

            if (char == " " || char == "\t") {
                i += 1
                continue
            }

            if (char.isDigit() || char == ".") {
                var num_str: String = ""
                while (i < expression.length() && 
                       (expression.charAt(i).isDigit() || expression.charAt(i).toString() == ".")) {
                    num_str += expression.charAt(i).toString()
                    i += 1
                }
                let num: Float64 = Float64.parse(num_str) match {
                    Some(value) => value,
                    None => return None
                }
                operand_stack.add(num)
                continue
            }

            if (char == "(") {
                operator_stack.add(char)
            } else if (char == ")") {
                while (!operator_stack.isEmpty() && operator_stack.last() != "(") {
                    let result = apply_operator(operand_stack, operator_stack)
                    operand_stack = result.0
                    operator_stack = result.1
                }
                if (!operator_stack.isEmpty()) {
                    operator_stack.removeLast() // Remove the '('
                }
            } else if (operators.containsKey(char)) {
                while (!operator_stack.isEmpty() && 
                       operator_stack.last() != "(" && 
                       precedence(operator_stack.last()) >= precedence(char)) {
                    let result = apply_operator(operand_stack, operator_stack)
                    operand_stack = result.0
                    operator_stack = result.1
                }
                operator_stack.add(char)
            }

            i += 1
        }

        while (!operator_stack.isEmpty()) {
            let result = apply_operator(operand_stack, operator_stack)
            operand_stack = result.0
            operator_stack = result.1
        }

        if (operand_stack.size() == 1) {
            return Some(operand_stack.get(0))
        } else {
            return None
        }
    }

    public func precedence(op: String): Int64 {
        /*
        Returns the priority of the specified operator, where the higher the priority the greater the assignment. The priority of '^' is greater than '/' and '*', and the priority of '/' and '*' is greater than '+' and '-'
        :param operator: String, given operator
        :return: Int64, the priority of the given operator, otherwise return 0
        >>> calculator = Calculator()
        >>> calculator.precedence('+')
        1
        >>> calculator.precedence('^')
        3
        */
        if (op == "+" || op == "-") {
            return 1
        } else if (op == "*" || op == "/") {
            return 2
        } else if (op == "^") {
            return 3
        } else {
            return 0
        }
    }

    public func apply_operator(operand_stack: ArrayList<Float64>, operator_stack: ArrayList<String>): (ArrayList<Float64>, ArrayList<String>) {
        /*
        Use the operator at the top of the operator stack to perform the operation on the two numbers at the top of the operator stack, and store the results at the top of the operator stack
        :param operand_stack:ArrayList<Float64>
        :param operator_stack:ArrayList<String>
        :return: the updated operand_stack and operator_stack
        >>> calculator = Calculator()
        >>> calculator.apply_operator(ArrayList<Float64>([1, 2, 3]), ArrayList<String>(['+', '-']))
        ([1, -1], ['-'])
        */
        if (operand_stack.size() < 2 || operator_stack.isEmpty()) {
            return (operand_stack, operator_stack)
        }

        let op: String = operator_stack.last()
        operator_stack.removeLast()
        let b: Float64 = operand_stack.last()
        operand_stack.removeLast()
        let a: Float64 = operand_stack.last()
        operand_stack.removeLast()

        if (operators.containsKey(op)) {
            let operation = operators.get(op) match {
                Some(op_func) => op_func,
                None => return (operand_stack, operator_stack)
            }
            let result: Float64 = operation(a, b)
            operand_stack.add(result)
        }

        return (operand_stack, operator_stack)
    }
}

import std.time.DateTime
import std.collection.ArrayList

class Event <: Equatable<Event> {

    /*
    This is a class as Event that represents a calendar event with date, time range, and description.
    It implements the Equatable interface to support event comparison.
    */

    let date: DateTime
    let start_time: DateTime
    let end_time: DateTime
    let description: String

    public init(date: DateTime, start_time: DateTime, end_time: DateTime, description: String) {
        /*
        Initialize a new Event instance with specified date, time range, and description.
        :param date: The date when the event occurs,DateTime.
        :param start_time: The start time of the event,DateTime.
        :param end_time: The end time of the event,DateTime.
        :param description: The descriptive text of the event,String.
        >>> let event = Event(DateTime.of(year: 2023, month: 12, dayOfMonth: 25, hour: 0, minute: 0), DateTime.of(year: 2023, month: 12, dayOfMonth: 25, hour: 10, minute: 0), DateTime.of(year: 2023, month: 12, dayOfMonth: 25, hour: 12, minute: 0), 'Christmas Party')
        >>> event.description
        'Christmas Party'
        */
        this.date = date
        this.start_time = start_time
        this.end_time = end_time
        this.description = description
    }

    public override operator func != (that: Event): Bool {
        /*
        Check if two events are not equal.
        Two events are considered not equal if any of their date, start_time, end_time, or description differ.
        :param that: The Event to compare with this Event,Event.
        :return: true if the events are not equal, false otherwise,Bool.
        >>> let event1 = Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1), DateTime.of(hour: 10), DateTime.of(hour: 11), 'Event 1')
        >>> let event2 = Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1), DateTime.of(hour: 110), DateTime.of(hour: 111), 'Event 2')
        >>> event1 != event2
        true
        */
        return this.date != that.date || this.start_time != that.start_time || this.end_time != that.end_time || this.description != that.description
    }

    public override operator func == (that: Event): Bool {
        /*
        Check if two events are equal.
        Two events are considered equal if their date, start_time, end_time, and description are all the same.
        :param that: The Event to compare with this Event,Event.
        :return: true if the events are equal, false otherwise,Bool.
        >>> let event1 = Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1), DateTime.of(hour: 10), DateTime.of(hour: 11), 'Event 1')
        >>> let event2 = Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1), DateTime.of(hour: 10), DateTime.of(hour: 11), 'Event 1')
        >>> event1 == event2
        true
        */
        return this.date == that.date && this.start_time == that.start_time && this.end_time == that.end_time && this.description == that.description
    }
}

class CalendarUtil {

    /*
    This is a class as CalendarUtil that provides functionalities to manage calendar events, schedule appointments, and perform conflict checks.
    */

    let events: ArrayList<Event>

    public init() {
        /*
        Initialize the calendar with an empty list of events.
        */
        this.events = ArrayList<Event>()
    }

    public func add_event(event: Event): Unit {
        /*
        Add an event to the calendar.
        :param event: The event to be added to the calendar,Event.
        >>> calendar = CalendarUtil()
        >>> calendar.add_event(Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0), 'New Year'))
        >>> calendar.events
        [Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0), 'New Year')]

        */
        this.events.add(event)
    }

    public func remove_event(event: Event): Unit {
        /*
        Remove an event from the calendar.
        :param event: The event to be removed from the calendar,Event.
        >>> calendar = CalendarUtil()
        >>> calendar.events = [Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0), 'New Year')]
        >>> calendar.remove_event(Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0), 'New Year'))
        >>> calendar.events
        []

        */
        let index = this.find_event_index(event)
        if index != -1 {
            this.events.remove(index)
        }
    }

    private func find_event_index(event: Event): Int64 {
        for i in 0..<this.events.size {
            if this.events[i] == event {
                return i
            }
        }
        return -1
    }

    public func get_events(date: DateTime): ArrayList<Event> {
        /*
        Get all events on a given date.
        :param date: The date to get events for,DateTime.
        :return: A list of events on the given date,ArrayList<Event>.
        >>> calendar = CalendarUtil()
        >>> calendar.events = [Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0), 'New Year')]
        >>> calendar.get_events(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0))
        [Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0), 'New Year')]

        */
        let result = ArrayList<Event>()
        for event in this.events {
            if event.date.year == date.year && event.date.month == date.month && event.date.dayOfMonth == date.dayOfMonth {
                result.add(event)
            }
        }
        return result
    }

    public func is_available(start_time: DateTime, end_time: DateTime): Bool {
        /*
        Check if the calendar is available for a given time slot.
        :param start_time: The start time of the time slot,DateTime.
        :param end_time: The end time of the time slot,DateTime.
        :return: true if the calendar is available for the given time slot, false otherwise,Bool.
        >>> calendar = CalendarUtil()
        >>> calendar.events = [Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0), 'New Year')]
        >>> calendar.is_available(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 1, minute: 0))
        false

        */
        for event in this.events {
            if event.date.year == start_time.year && event.date.month == start_time.month && event.date.dayOfMonth == start_time.dayOfMonth {
                if (start_time < event.end_time) && (end_time > event.start_time) {
                    return false
                }
            }
        }
        return true
    }

    public func get_available_slots(date: DateTime): ArrayList<(DateTime, DateTime)> {
        /*
        Get all available time slots on a given date.
        :param date: The date to get available time slots for,DateTime.
        :return: A list of available time slots on the given date,ArrayList<(DateTime, DateTime)>.
        >>> calendar = CalendarUtil()
        >>> calendar.events = [Event(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 0, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 23, minute: 0), 'New Year')]
        >>> calendar.get_available_slots(DateTime.of(year: 2023, month: 1, dayOfMonth: 1))
        [(DateTime.of(year: 2023, month: 1, dayOfMonth: 1, hour: 23, minute: 0), DateTime.of(year: 2023, month: 1, dayOfMonth: 2, hour: 0, minute: 0))]

        */
        let available_slots = ArrayList<(DateTime, DateTime)>()
        let day_start = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 0, minute: 0)
        let day_end = DateTime.of(year: date.year, month: date.month, dayOfMonth: date.dayOfMonth, hour: 23, minute: 59)

        // If there are no events on this date, the entire day is available
        let events_on_date = this.get_events(date)
        if events_on_date.isEmpty() {
            available_slots.add((day_start, day_end.addMinutes(1)))
            return available_slots
        }

        // Sort events by start time
        var sorted_events = events_on_date.toArray().toArrayList()
        this.sort_events_by_start_time(sorted_events)

        // Check availability from day start to first event
        if sorted_events[0].start_time > day_start {
            available_slots.add((day_start, sorted_events[0].start_time))
        }

        // Check availability between events
        for i in 1..<sorted_events.size {
            let prev_event = sorted_events[i-1]
            let curr_event = sorted_events[i]
            if prev_event.end_time < curr_event.start_time {
                available_slots.add((prev_event.end_time, curr_event.start_time))
            }
        }

        // Check availability from last event to day end
        let last_event = sorted_events[sorted_events.size - 1]
        if last_event.end_time < day_end.addMinutes(1) {
            available_slots.add((last_event.end_time, day_end.addMinutes(1)))
        }

        return available_slots
    }

    private func sort_events_by_start_time(events: ArrayList<Event>): Unit {
        for i in 0..<events.size - 1 {
            for j in 0..<events.size - 1 - i {
                if events[j].start_time > events[j+1].start_time {
                    let temp = events[j]
                    events[j] = events[j+1]
                    events[j+1] = temp
                }
            }
        }
    }

    public func get_upcoming_events(num_events: Int64): ArrayList<Event> {
        /*
        Get the next n upcoming events from a given date.
        :param date: The date to get upcoming events from,DateTime.
        :param n: The number of upcoming events to get,Int64.
        :return: A list of the next n upcoming events from the given date,ArrayList<Event>.
        >>> calendar = CalendarUtil()
        >>> calendar.events = [Event(DateTime.of(year: DateTime.now().year+1, month: 1, dayOfMonth: 3, hour: 0, minute: 0), DateTime.of(year: DateTime.now().year+1, month: 1, dayOfMonth: 3, hour: 1, minute: 0), DateTime.of(year: DateTime.now().year+1, month: 1, dayOfMonth: 3, hour: 2, minute: 0), "New Year 3")]
        >>> calendar.get_upcoming_events(1)
        [Event(DateTime.of(year: DateTime.now().year+1, month: 1, dayOfMonth: 3, hour: 0, minute: 0), DateTime.of(year: DateTime.now().year+1, month: 1, dayOfMonth: 3, hour: 1, minute: 0), DateTime.of(year: DateTime.now().year+1, month: 1, dayOfMonth: 3, hour: 2, minute: 0), "New Year 3")]

        */
        let now = DateTime.now()
        let upcoming_events = ArrayList<Event>()

        // Filter events that are in the future
        for event in this.events {
            if event.start_time > now {
                upcoming_events.add(event)
            }
        }

        // Sort upcoming events by start time
        this.sort_events_by_start_time(upcoming_events)

        // Limit to num_events
        let result = ArrayList<Event>()
        let count = min(upcoming_events.size, num_events)
        for i in 0..<count {
            result.add(upcoming_events[i])
        }

        return result
    }
}

import std.collection.HashMap

class CamelCaseMap {

    /*
    This is a custom class that allows keys to be in camel case style by converting them from underscore style, which provides dictionary-like functionality.
    */

    let _data: HashMap<String, Any>

    public init() {
        /*
        Initialize data to an empty dictionary
        */
        _data = HashMap<String, Any>()
    }

    public func __getitem__(key: String): Any {
        /*
        Return the value corresponding to the key
        :param key:String
        :return:Any,the value corresponding to the key
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__getitem__('first_name')
        'John'
        */
        let camelKey = CamelCaseMap._to_camel_case(key: key)
        return _data[camelKey]
    }

    public func __setitem__(key: String, value: Any): Unit {
        /*
        Set the value corresponding to the key to the specified value
        :param key:String
        :param value:Any, the specified value
        :return:Unit
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__setitem__('first_name', 'new name')
        >>> camelize_map.__getitem__('first_name')
        'new name'
        */
        let camelKey = CamelCaseMap._to_camel_case(key: key)
        _data[camelKey] = value
    }

    public func __delitem__(key: String): Unit {
        /*
        Delete the value corresponding to the key
        :param key:String
        :return:Unit
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__delitem__('first_name')
        >>> flag = camelize_map._data.contains(camelize_map.to_camel_case('first_name'))
        flag = false
        */
        let camelKey = CamelCaseMap._to_camel_case(key: key)
        _data.remove(camelKey)
    }

    public func __len__(): Int64 {
        /*
        Returns the length of the own data
        :return:Int64, length of data
        >>> camelize_map = CamelCaseMap()
        >>> camelize_map.__setitem__('first_name', 'John')
        >>> camelize_map.__setitem__('last_name', 'Doe')
        >>> camelize_map.__setitem__('age', 30)
        >>> camelize_map.__len__()
        3
        */
        return _data.size
    }

    public func _convert_key(key: Any): Any {
        /*
        convert key string into camel case
        If key is not String type, return key directly
        :param key:Any
        :return:Any, converted key string
        >>> camelize_map = CamelCaseMap()
        >>> (camelize_map._convert_key('first_name') as String) ?? ""
        'firstName'
        >>> (camelize_map._convert_key(123) as Int64) ?? 0
        123
        */
        if (key is String) {
            return CamelCaseMap._to_camel_case(key: key as String)
        } else {
            return key
        }
    }

    public static func _to_camel_case(key: String): String {
        /*
        convert key string into camel case
        :param key:String
        :return:String, converted key string
        >>> CamelCaseMap._to_camel_case('first_name')
        'firstName'
        */
        if (key.isEmpty()) {
            return key
        }

        let parts = key.split("_")
        if (parts.size <= 1) {
            return key
        }

        var result = parts[0]
        var i: Int64 = 1
        while (i < parts.size) {
            if (!parts[i].isEmpty()) {
                let part = parts[i]
                let firstChar = part.substring(0, 1).toUpper()
                let rest = part.substring(1, part.size)
                result = result + firstChar + rest
            }
            i = i + 1
        }

        return result
    }
}

import std.collection.ArrayList

class ChandrasekharSieve {

    /*
    This is a class that uses the Chandrasekhar's Sieve method to find all prime numbers within the range
    */

    let n: Int64
    var primes: ArrayList<Int64> = ArrayList<Int64>()

    public init(n: Int64) {
        /*
        Initialize the ChandrasekharSieve class with the given limit.
        :param n: Int64, the upper limit for generating prime numbers
        */
        this.n = n
        this.primes = generate_primes()
    }

    public func generate_primes(): ArrayList<Int64> {
        /*
        Generate prime numbers up to the specified limit using the Chandrasekhar sieve algorithm.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.generate_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        if n < 2 {
            return ArrayList<Int64>()
        }

        // Create a boolean array to mark primes
        var is_prime: ArrayList<Bool> = ArrayList<Bool>()
        for i in 0..n + 1 {
            is_prime.add(true)
        }

        is_prime.set(0, false)
        if n >= 1 {
            is_prime.set(1, false)
        }

        var p: Int64 = 2
        while p * p <= n {
            if is_prime.get(p.toInt()).getOrThrow() {
                // Mark all multiples of p as not prime
                var i: Int64 = p * p
                while i <= n {
                    is_prime.set(i.toInt(), false)
                    i = i + p
                }
            }
            p = p + 1
        }

        // Collect all prime numbers
        var result: ArrayList<Int64> = ArrayList<Int64>()
        for i in 2..n + 1 {
            if is_prime.get(i.toInt()).getOrThrow() {
                result.add(i)
            }
        }

        return result
    }

    public func get_primes(): ArrayList<Int64> {
        /*
        Get the list of generated prime numbers.
        :return: ArrayList<Int64>, a list of prime numbers
        >>> cs = ChandrasekharSieve(20)
        >>> cs.get_primes()
        [2, 3, 5, 7, 11, 13, 17, 19]

        */
        return this.primes
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.time.DateTime

class Message <: Equatable<Message> {

    /*
    This is a Message class representing a message in a chat system.
    It contains information about the sender, receiver, message content, and timestamp.
    */

    let sender: String
    let receiver: String
    let message: String
    let timestamp: String

    public init(sender: String, receiver: String, message: String, timestamp: String) {
        /*
        Initialize a Message object with sender, receiver, message content, and timestamp.
        :param sender: The username of the sender, String.
        :param receiver: The username of the receiver, String.
        :param message: The content of the message, String.
        :param timestamp: The time when the message was sent, String.
        >>> let msg = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> msg.sender
        "John"
        >>> msg.receiver
        "Mary"
        >>> msg.message
        "Hello"
        >>> msg.timestamp
        "2023-01-01 00:00:00"
        */
        this.sender = sender
        this.receiver = receiver
        this.message = message
        this.timestamp = timestamp
    }

    public override operator func != (that: Message): Bool {
        /*
        Check if two Message objects are not equal.
        Two messages are considered not equal if any of their sender, receiver, message, or timestamp differ.
        :param that: Another Message object to compare with.
        :return: True if the messages are not equal, False otherwise.
        >>> let msg1 = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> let msg2 = Message("John", "Mary", "Hi", "2023-01-01 00:00:00")
        >>> msg1 != msg2
        true
        */
        return this.sender != that.sender || this.receiver != that.receiver || this.message != that.message || this.timestamp != that.timestamp
    }

    public override operator func == (that: Message): Bool {
        /*
        Check if two Message objects are equal.
        Two messages are considered equal if their sender, receiver, message, and timestamp are all the same.
        :param that: Another Message object to compare with.
        :return: True if the messages are equal, False otherwise.
        >>> let msg1 = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> let msg2 = Message("John", "Mary", "Hello", "2023-01-01 00:00:00")
        >>> let msg3 = Message("Mary", "John", "Hello", "2023-01-01 00:00:00")
        >>> msg1 == msg2
        true
        >>> msg1 == msg3
        false
        */
        return this.sender == that.sender && this.receiver == that.receiver && this.message == that.message && this.timestamp == that.timestamp
    }
}

class Chat {

    /*
    This is a chat class with the functions of adding users, removing users, sending messages, and obtaining messages.
    */

    let users: HashMap<String, ArrayList<Message>>

    public init() {
        /*
        Initialize the Chat with an attribute users, which is an empty dictionary.
        */
        this.users = HashMap<String, ArrayList<Message>>()
    }

    public func add_user(username: String): Bool {
        /*
        Add a new user to the Chat.
        :param username: The user's name, String.
        :return: If the user is already in the Chat, returns false, otherwise, returns true.
        >>> chat = Chat()
        >>> chat.add_user('John')
        true
        this.users = {'John': []}
        >>> chat.add_user('John')
        false

        */
        if (this.users.contains(username)) {
            return false
        } else {
            this.users.add(username, ArrayList<Message>())
            return true
        }
    }

    public func remove_user(username: String): Bool {
        /*
        Remove a user from the Chat.
        :param username: The user's name, String.
        :return: If the user is already in the Chat, returns true, otherwise, returns false.
        >>> chat = Chat()
        >>> chat.users = {'John': []}
        >>> chat.remove_user('John')
        true
        >>> chat.remove_user('John')
        false

        */
        if (this.users.contains(username)) {
            this.users.remove(username)
            return true
        } else {
            return false
        }
    }

    public func send_message(sender: String, receiver: String, message: String): Bool {
        /*
        Send a message from a user to another user.
        :param sender: The sender's name, String.
        :param receiver: The receiver's name, String.
        :param message: The message, String.
        :return: If the sender or the receiver is not in the Chat, returns false, otherwise, returns true.
        >>> chat = Chat()
        >>> chat.users = {'John': [], 'Mary': []}
        >>> chat.send_message('John', 'Mary', 'Hello')
        true
        >>> chat.send_message('John', 'Tom', 'Hello')
        false

        */
        if (!this.users.contains(sender) || !this.users.contains(receiver)) {
            return false
        }

        let currentTime = DateTime.now(TimeZone.systemDefault())
        let timestamp = currentTime.toString()
        let msg = Message(sender, receiver, message, timestamp)

        var senderMessages = this.users.get(sender).getOrThrow()
        senderMessages.add(msg)

        var receiverMessages = this.users.get(receiver).getOrThrow()
        receiverMessages.add(msg)

        return true
    }

    public func get_messages(username: String): ArrayList<Message> {
        /*
        Get all the messages of a user from the Chat.
        :param username: The user's name, String.
        :return: A list of messages, each message is a Message object.
        >>> chat = Chat()
        >>> chat.users = {'John': ArrayList<Message>([Message('John', 'Mary', 'Hello', '2023-01-01 00:00:00')]), 'Mary': []}
        >>> chat.get_messages('John')
        ArrayList<Message>([Message('John', 'Mary', 'Hello', '2023-01-01 00:00:00')])
        >>> chat.get_messages('Mary')
        []

        */
        if (this.users.contains(username)) {
            return this.users.get(username).getOrThrow()
        } else {
            return ArrayList<Message>()
        }
    }
}

