class DataStatistics {

    /*
    This is a class for performing data statistics, supporting to calculate the mean, median, and mode of a given data set.
    */

    public func mean(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the average value of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the mean value
        >>> ds = DataStatistics()
        >>> ds.mean(ArrayList<Int64>([1, 2, 3, 4, 5]))
        3.00
        */
        if (data.size() == 0) {
            return 0.0
        }

        var sum: Float64 = 0.0
        for (i: Int64 = 0; i < data.size(); i = i + 1) {
            sum = sum + data.get(i).toFloat64()
        }

        var meanValue: Float64 = sum / data.size().toFloat64()
        // Round to 2 decimal places
        meanValue = round(meanValue * 100.0) / 100.0
        return meanValue
    }

    public func median(data: ArrayList<Int64>): Float64 {
        /*
        Calculate the median of a group of data, accurate to two digits after the Decimal separator
        :param data:ArrayList<Int64>, data list
        :return:Float64, the median value
        >>> ds = DataStatistics()
        >>> ds.median(ArrayList<Int64>([2, 5, 1, 3, 4]))
        3.00
        */
        if (data.size() == 0) {
            return 0.0
        }

        // Create a copy of the data to sort
        var sortedData: ArrayList<Int64> = ArrayList<Int64>()
        for (i: Int64 = 0; i < data.size(); i = i + 1) {
            sortedData.add(data.get(i))
        }

        // Sort the data
        sort<Int64>(sortedData)

        var size: Int64 = sortedData.size()
        var medianValue: Float64

        if (size % 2 == 1) {
            // Odd number of elements
            medianValue = sortedData.get(size / 2).toFloat64()
        } else {
            // Even number of elements
            var mid1: Float64 = sortedData.get(size / 2 - 1).toFloat64()
            var mid2: Float64 = sortedData.get(size / 2).toFloat64()
            medianValue = (mid1 + mid2) / 2.0
        }

        // Round to 2 decimal places
        medianValue = round(medianValue * 100.0) / 100.0
        return medianValue
    }

    public func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        /*
        Calculate the mode of a set of data
        :param data:ArrayList<Int64>, data list
        :return:ArrayList<Int64>, the mode
        >>> ds = DataStatistics()
        >>> ds.mode(ArrayList<Int64>([2, 2, 3, 3, 4]))
        [2, 3]
        */
        if (data.size() == 0) {
            return ArrayList<Int64>()
        }

        // Count frequency of each element
        var frequencyMap: HashMap<Int64, Int64> = HashMap<Int64, Int64>()
        for (i: Int64 = 0; i < data.size(); i = i + 1) {
            var value: Int64 = data.get(i)
            var count: Int64 = frequencyMap.get(value).getOrThrow(0)
            frequencyMap.set(value, count + 1)
        }

        // Find the maximum frequency
        var maxFreq: Int64 = 0
        for (entry: (Int64, Int64) in frequencyMap) {
            if (entry.1 > maxFreq) {
                maxFreq = entry.1
            }
        }

        // Collect all elements with maximum frequency
        var modeList: ArrayList<Int64> = ArrayList<Int64>()
        for (entry: (Int64, Int64) in frequencyMap) {
            if (entry.1 == maxFreq) {
                modeList.add(entry.0)
            }
        }

        // Sort the mode list for consistent output
        sort<Int64>(modeList)

        return modeList
    }
}

import std.collection.ArrayList
import std.math.round
import std.math.sqrt
import std.math.abs

class DataStatistics2 {

    /*
    This is a class for performing data statistics, supporting to get the sum, minimum, maximum, variance, standard deviation, and correlation of a given dataset.
    */

    let data: ArrayList<Float64>

    public init(data: ArrayList<Float64>) {
        /*
        Initialize Data List
        :param data:ArrayList<Float64>
        */
        this.data = data
    }

    public func get_sum(): Float64 {
        /*
        Calculate the sum of data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_sum()
        10.0
        */
        var sum: Float64 = 0.0
        for i in 0 ..< this.data.size {
            sum += this.data[i]
        }
        return sum
    }

    public func get_min(): Float64 {
        /*
        Calculate the minimum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_min()
        1.0
        */
        if this.data.size == 0 {
            return 0.0
        }
        var min_val: Float64 = this.data[0]
        for i in 1 ..< this.data.size {
            if this.data[i] < min_val {
                min_val = this.data[i]
            }
        }
        return min_val
    }

    public func get_max(): Float64 {
        /*
        Calculate the maximum value in the data
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_max()
        4.0
        */
        if this.data.size == 0 {
            return 0.0
        }
        var max_val: Float64 = this.data[0]
        for i in 1 ..< this.data.size {
            if this.data[i] > max_val {
                max_val = this.data[i]
            }
        }
        return max_val
    }

    public func get_variance(): Float64 {
        /*
        Calculate variance, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_variance()
        1.25
        */
        if this.data.size == 0 {
            return 0.0
        }

        // Calculate mean
        let mean = this.get_sum() / Float64(this.data.size)

        // Calculate variance
        var sum_sq_diff: Float64 = 0.0
        for i in 0 ..< this.data.size {
            let diff = this.data[i] - mean
            sum_sq_diff += diff * diff
        }
        let variance = sum_sq_diff / Float64(this.data.size)

        // Round to 2 decimal places
        return round(variance * 100.0) / 100.0
    }

    public func get_std_deviation(): Float64 {
        /*
        Calculate standard deviation, accurate to two digits after the Decimal separator
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_std_deviation()
        1.12
        */
        let variance = this.get_variance()
        let std_dev = sqrt(variance)

        // Round to 2 decimal places
        return round(std_dev * 100.0) / 100.0
    }

    public func get_correlation(): Float64 {
        /*
        Calculate correlation
        :return:Float64
        >>> ds2 = DataStatistics2(ArrayList<Float64>([1.0, 2.0, 3.0, 4.0]))
        >>> ds2.get_correlation()
        1.0
        */
        // For a single dataset, we'll calculate the correlation of the dataset with its indices
        // This would result in a perfect correlation for a sequence like [1.0, 2.0, 3.0, 4.0]
        if this.data.size <= 1 {
            return 1.0
        }

        // Calculate mean of data
        let mean_x = this.get_sum() / Float64(this.data.size)

        // Calculate mean of indices (0, 1, 2, ...)
        var sum_indices: Float64 = 0.0
        for i in 0 ..< this.data.size {
            sum_indices += Float64(i)
        }
        let mean_y = sum_indices / Float64(this.data.size)

        // Calculate numerator and denominators for correlation
        var sum_xy: Float64 = 0.0
        var sum_x_sq: Float64 = 0.0
        var sum_y_sq: Float64 = 0.0

        for i in 0 ..< this.data.size {
            let x_diff = this.data[i] - mean_x
            let y_diff = Float64(i) - mean_y
            sum_xy += x_diff * y_diff
            sum_x_sq += x_diff * x_diff
            sum_y_sq += y_diff * y_diff
        }

        let denominator = sqrt(sum_x_sq * sum_y_sq)
        if denominator == 0.0 {
            return 0.0
        }

        let correlation = sum_xy / denominator

        // Round to 2 decimal places
        return round(correlation * 100.0) / 100.0
    }
}

import std.collection.ArrayList
import std.math.sqrt
import std.math.exp
import std.math.abs

class DataStatistics4 {

    /*
    This is a class that performs advanced mathematical calculations and statistics, including correlation coefficient, skewness, kurtosis, and probability density function (PDF) for a normal distribution.
    */

    public static func correlation_coefficient(data1: ArrayList<Float64>, data2: ArrayList<Float64>): Float64 {
        /*
        Calculate the correlation coefficient of two sets of data.
        :param data1: The first set of data,ArrayList<Float64>.
        :param data2: The second set of data,ArrayList<Float64>.
        :return: The correlation coefficient, Float64.
        >>> DataStatistics4.correlation_coefficient(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]))
        0.9999999999999998

        */
        if data1.size != data2.size || data1.size == 0 {
            return 0.0
        }

        let n = data1.size
        var sum1: Float64 = 0.0
        var sum2: Float64 = 0.0
        var sum1Sq: Float64 = 0.0
        var sum2Sq: Float64 = 0.0
        var pSum: Float64 = 0.0

        for i in 0..<n {
            let val1 = data1[i]
            let val2 = data2[i]
            sum1 += val1
            sum2 += val2
            sum1Sq += val1 * val1
            sum2Sq += val2 * val2
            pSum += val1 * val2
        }

        let num = pSum - (sum1 * sum2 / Float64(n))
        let den = sqrt((sum1Sq - (sum1 * sum1 / Float64(n))) * (sum2Sq - (sum2 * sum2 / Float64(n))))

        if den == 0.0 {
            return 0.0
        }

        return num / den
    }

    public static func skewness(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the skewness of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The skewness, Float64.
        >>> DataStatistics4.skewness(ArrayList<Float64>([1.0, 2.0, 5.0]))
        2.3760224064818463

        */
        let n = data.size
        if n < 3 {
            return 0.0
        }

        // Calculate mean
        var mean: Float64 = 0.0
        for i in 0..<n {
            mean += data[i]
        }
        mean /= Float64(n)

        // Calculate standard deviation
        var m2: Float64 = 0.0
        for i in 0..<n {
            let diff = data[i] - mean
            m2 += diff * diff
        }
        let variance = m2 / Float64(n)
        let stdDev = sqrt(variance)

        if stdDev == 0.0 {
            return 0.0
        }

        // Calculate skewness
        var m3: Float64 = 0.0
        for i in 0..<n {
            let diff = (data[i] - mean) / stdDev
            m3 += diff * diff * diff
        }

        let skewness = m3 / Float64(n)
        return skewness
    }

    public static func kurtosis(data: ArrayList<Float64>): Float64 {
        /*
        Calculate the kurtosis of a set of data.
        :param data: The input data list, ArrayList<Float64>.
        :return: The kurtosis, Float64.
        >>> DataStatistics4.kurtosis(ArrayList<Float64>([1.0, 2.0, 5.0]))
        -1.5000000000000007

        */
        let n = data.size
        if n < 4 {
            return 0.0
        }

        // Calculate mean
        var mean: Float64 = 0.0
        for i in 0..<n {
            mean += data[i]
        }
        mean /= Float64(n)

        // Calculate variance and 4th moment
        var m2: Float64 = 0.0
        var m4: Float64 = 0.0
        for i in 0..<n {
            let diff = data[i] - mean
            let diffSq = diff * diff
            m2 += diffSq
            m4 += diffSq * diffSq
        }

        let variance = m2 / Float64(n)
        if variance == 0.0 {
            return 0.0
        }

        let kurtosis = (m4 / Float64(n)) / (variance * variance)
        return kurtosis - 3.0  // Excess kurtosis
    }

    public static func pdf(data: ArrayList<Float64>, mu: Float64, sigma: Float64): ArrayList<Float64> {
        /*
        Calculate the probability density function (PDF) of a set of data under a normal distribution.
        :param data: The input data list, ArrayList<Float64>.
        :param mu: The mean of the normal distribution, Float64.
        :param sigma: The standard deviation of the normal distribution, Float64.
        :return: The probability density function (PDF), ArrayList<Float64>.
        >>> DataStatistics4.pdf(ArrayList<Float64>([1.0, 2.0, 3.0]), 1.0, 1.0)
        [0.3989422804014327, 0.24197072451914337, 0.05399096651318806]

        */
        if sigma <= 0.0 {
            // Return array of zeros if sigma is invalid
            let result = ArrayList<Float64>()
            for i in 0..<data.size {
                result.add(0.0)
            }
            return result
        }

        let result = ArrayList<Float64>()
        let sqrt2Pi = sqrt(2.0 * 3.14159265358979323846)  // Using pi approximation
        let coeff = 1.0 / (sigma * sqrt2Pi)

        for i in 0..<data.size {
            let x = data[i]
            let exponent = -0.5 * ((x - mu) / sigma) * ((x - mu) / sigma)
            let pdfValue = coeff * exp(exponent)
            result.add(pdfValue)
        }

        return result
    }
}

import std.collection.ArrayList

class DecryptionUtils {

    /*
    This is a class that provides methods for decryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the decryption utility with a key.
        :param key: The key to use for decryption,String.
        */
        this.key = key
    }

    public func caesar_decipher(ciphertext: String, shift: Int64): String {
        /*
        Deciphers the given ciphertext using the Caesar cipher
        :param ciphertext: The ciphertext to decipher,String.
        :param shift: The shift to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.caesar_decipher('ifmmp', 1)
        'hello'

        */
        var result = ""
        let runes = ciphertext.runes()
        for (r in runes) {
            if (r >= r'a' && r <= r'z') {
                var shifted = r - shift as Rune
                if (shifted < r'a') {
                    shifted = shifted + 26 as Rune
                }
                result = result + shifted.toString()
            } else if (r >= r'A' && r <= r'Z') {
                var shifted = r - shift as Rune
                if (shifted < r'A') {
                    shifted = shifted + 26 as Rune
                }
                result = result + shifted.toString()
            } else {
                result = result + r.toString()
            }
        }
        return result
    }

    public func vigenere_decipher(ciphertext: String): String {
        /*
        Deciphers the given ciphertext using the Vigenere cipher
        :param ciphertext: The ciphertext to decipher,String.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.vigenere_decipher('ifmmp')
        'ybocl'

        */
        if (this.key.isEmpty()) {
            return ciphertext
        }

        var result = ""
        let ciphertextRunes = ciphertext.runes()
        let keyRunes = this.key.runes()
        var keyIndex = 0 as Int64

        for (r in ciphertextRunes) {
            let keyRune = keyRunes[(keyIndex % this.key.length()) as Int64]
            if (r >= r'a' && r <= r'z') {
                let base = r'a'
                let keyBase = r'a'
                let shifted = ((r - base) - (keyRune - keyBase)) % 26
                let shiftedRune = if (shifted < 0) { (shifted + 26) + base as Rune } else { shifted + base as Rune }
                result = result + shiftedRune.toString()
                keyIndex = keyIndex + 1
            } else if (r >= r'A' && r <= r'Z') {
                let base = r'A'
                let keyBase = r'a'
                let shifted = ((r - base) - (keyRune - keyBase)) % 26
                let shiftedRune = if (shifted < 0) { (shifted + 26) + base as Rune } else { shifted + base as Rune }
                result = result + shiftedRune.toString()
                keyIndex = keyIndex + 1
            } else {
                result = result + r.toString()
            }
        }
        return result
    }

    public func rail_fence_decipher(encrypted_text: String, rails: Int64): String {
        /*
        Deciphers the given ciphertext using the Rail Fence cipher
        :param encrypted_text: The ciphertext to decipher,String.
        :param rails: The number of rails to use for decryption,Int64.
        :return: The deciphered plaintext,String.
        >>> d = DecryptionUtils('key')
        >>> d.rail_fence_decipher('Hoo!el,Wrdl l', 3)
        'Hello, World!'

        */
        if (encrypted_text.isEmpty() || rails <= 0) {
            return encrypted_text
        }

        if (rails == 1) {
            return encrypted_text
        }

        let n = encrypted_text.length() as Int64
        // Create a 2D array to represent the rail fence
        var railMatrix = ArrayList<ArrayList<Rune>>()

        // Initialize the rail matrix with empty spaces
        for (i in 0 ..< rails) {
            let row = ArrayList<Rune>()
            for (j in 0 ..< n) {
                row.add(r' ')  // Placeholder
            }
            railMatrix.add(row)
        }

        // Mark the positions where characters should go
        var dir_down = false
        var row = 0 as Int64
        var col = 0 as Int64

        for (i in 0 ..< n) {
            if (row == 0 || row == rails - 1) {
                dir_down = !dir_down
            }

            // Mark this position with a special marker
            railMatrix[row as Int64][col as Int64] = r'*'

            col = col + 1
            if (dir_down) {
                row = row + 1
            } else {
                row = row - 1
            }
        }

        // Fill the rail matrix with the encrypted text
        var index = 0 as Int64
        let encryptedRunes = encrypted_text.runes()
        for (i in 0 ..< rails) {
            for (j in 0 ..< n) {
                if (railMatrix[i][j] == r'*') {
                    railMatrix[i][j] = encryptedRunes[index]
                    index = index + 1
                }
            }
        }

        // Read the message in zigzag pattern
        var result = ""
        row = 0 as Int64
        col = 0 as Int64
        dir_down = false

        for (i in 0 ..< n) {
            if (row == 0 || row == rails - 1) {
                dir_down = !dir_down
            }

            result = result + railMatrix[row as Int64][col as Int64].toString()
            col = col + 1
            if (dir_down) {
                row = row + 1
            } else {
                row = row - 1
            }
        }

        return result
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.collection.ArrayDeque

class EightPuzzle {

    /*
    This class is an implementation of the classic 8-puzzle game, including methods for finding the blank tile, making moves, getting possible moves, and solving the puzzle using a breadth-first search algorithm.
    */

    let initial_state: ArrayList<ArrayList<Int64>>
    let goal_state: ArrayList<ArrayList<Int64>>

    public init(initial_state: ArrayList<ArrayList<Int64>>) {
        /*
        Initializing the initial state of Eight Puzzle Game, stores in attribute this.initial_state.
        And set the goal state of this game, stores in this.goal_state. In this case, set the size as 3*3
        :param initial_state: a 3*3 size list of Integer, stores the initial state
        */
        this.initial_state = initial_state
        this.goal_state = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 8, 0])])
    }

    public func find_blank(state: ArrayList<ArrayList<Int64>>): (Int64, Int64) {
        /*
        Find the blank position of current state, which is the 0 element.
        :param state: a 3*3 size list of Integer, stores the current state.
        :return i, j: two Int64egers, represent the coordinate of the blank block.
        >>> eightPuzzle = EightPuzzle(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        >>> eightPuzzle.find_blank(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        (2, 1)
        */
        for (i in 0..3) {
            for (j in 0..3) {
                if (state[i][j] == 0) {
                    return (i, j)
                }
            }
        }
        return (0, 0)  // fallback, should not happen in valid puzzle
    }

    public func move(state: ArrayList<ArrayList<Int64>>, direction: String): ArrayList<ArrayList<Int64>> {
        /*
        Find the blank block, then makes the board moves forward the given direction.
        :param state: a 3*3 size list of Integer, stores the state before moving.
        :param direction: String, only has 4 direction 'up', 'down', 'left', 'right'
        :return new_state: a 3*3 size list of Integer, stores the state after moving.
        >>> eightPuzzle.move(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]), 'left')
        [[2, 3, 4], [5, 8, 1], [0, 6, 7]]
        */
        // Create a deep copy of the state
        var new_state = ArrayList<ArrayList<Int64>>()
        for (i in 0..3) {
            var row = ArrayList<Int64>()
            for (j in 0..state[i].size()) {
                row.add(state[i][j])
            }
            new_state.add(row)
        }

        let (blank_row, blank_col) = this.find_blank(state)
        var new_blank_row = blank_row
        var new_blank_col = blank_col

        if (direction == "up" && blank_row > 0) {
            new_blank_row = blank_row - 1
        } else if (direction == "down" && blank_row < 2) {
            new_blank_row = blank_row + 1
        } else if (direction == "left" && blank_col > 0) {
            new_blank_col = blank_col - 1
        } else if (direction == "right" && blank_col < 2) {
            new_blank_col = blank_col + 1
        } else {
            return state  // invalid move, return original state
        }

        // Swap the blank with the target tile
        let temp = new_state[blank_row][blank_col]
        new_state[blank_row][blank_col] = new_state[new_blank_row][new_blank_col]
        new_state[new_blank_row][new_blank_col] = temp

        return new_state
    }

    public func get_possible_moves(state: ArrayList<ArrayList<Int64>>): ArrayList<String> {
        /*
        According the current state, find all the possible moving directions. Only has 4 direction 'up', 'down', 'left', 'right'.
        :param state: a 3*3 size list of Integer, stores the current state.
        :return moves: a list of String, store all the possible moving directions according to the current state.
        >>> eightPuzzle.get_possible_moves(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([2, 3, 4]), ArrayList<Int64>([5, 8, 1]), ArrayList<Int64>([6, 0, 7])]))
        ['up', 'left', 'right']
        */
        var moves = ArrayList<String>()
        let (blank_row, blank_col) = this.find_blank(state)

        if (blank_row > 0) {
            moves.add("up")
        }
        if (blank_row < 2) {
            moves.add("down")
        }
        if (blank_col > 0) {
            moves.add("left")
        }
        if (blank_col < 2) {
            moves.add("right")
        }

        return moves
    }

    public func solve(): ArrayList<String> {
        /*
        Use BFS algorithm to find the path solution which makes the initial state to the goal method.
        Maintain a list as a queue, named as open_list, append the initial state.
        Always visit and pop the 0 index element, invoke get_possible_moves method find all the possible directions.
        Traversal the possible_moves list and invoke move method to get several new states.Then append them.
        redo the above steps until the open_list is empty or the state has changed to the goal state.
        :return path: list of String, the solution to the goal state.
        >>> eightPuzzle = EightPuzzle(ArrayList<ArrayList<Int64>>([ArrayList<Int64>([1, 2, 3]), ArrayList<Int64>([4, 5, 6]), ArrayList<Int64>([7, 0, 8])]))
        >>> eightPuzzle.solve()
        ['right']
        */
        var queue = ArrayDeque<(ArrayList<ArrayList<Int64>>, ArrayList<String>)>()
        var visited = HashMap<String, Bool>()

        queue.add((this.initial_state, ArrayList<String>()))

        while (!queue.isEmpty()) {
            let (current_state, path) = queue.removeFirst()

            // Convert state to string for hashing
            var state_str = ""
            for (i in 0..3) {
                for (j in 0..current_state[i].size()) {
                    state_str = state_str + current_state[i][j].toString()
                }
            }

            if (visited.get(state_str).getOrThrowWithDefault(false)) {
                continue
            }

            visited.add(state_str, true)

            // Check if current state is the goal state
            var is_goal = true
            for (i in 0..3) {
                for (j in 0..current_state[i].size()) {
                    if (current_state[i][j] != this.goal_state[i][j]) {
                        is_goal = false
                        break
                    }
                }
                if (!is_goal) {
                    break
                }
            }

            if (is_goal) {
                return path
            }

            // Get possible moves
            var possible_moves = this.get_possible_moves(current_state)

            // For each possible move, create new state and add to queue
            for (move in possible_moves) {
                var new_state = this.move(current_state, move)
                var new_path = ArrayList<String>()
                for (i in 0..path.size()) {
                    new_path.add(path[i])
                }
                new_path.add(move)
                queue.add((new_state, new_path))
            }
        }

        // Return empty path if no solution found
        return ArrayList<String>()
    }
}

import std.time.DateTime
import std.collection.ArrayList
import std.collection.HashMap

class EmailClient {

    /*
    This is a class that serves as an email client, implementing functions such as checking emails, determining whether there is sufficient space, and cleaning up space
    */

    let addr: String
    let capacity: Int64
    var inbox: ArrayList<HashMap<String, Any>>

    public init(addr: String, capacity: Int64) {
        /*
        Initializes the EmailClient class with the email address and the capacity of the email box.
        :param addr: The email address, String.
        :param capacity: The capacity of the email box, Int64.
        */
        this.addr = addr
        this.capacity = capacity
        this.inbox = ArrayList<HashMap<String, Any>>()
    }

    public func send_to(recv: EmailClient, content: String, size: Int64): Bool {
        /*
        Sends an email to the given email address.
        :param recv: The email address of the receiver, String.
        :param content: The content of the email, String.
        :param size: The size of the email, Int64.
        :return: true if the email is sent successfully, false if the receiver's email box is full.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> sender.send_to(receiver, 'Hello', 10)
        true
        >>> receiver.inbox
        {'sender': 'sender@example.com', 'receiver': 'receiver@example.com', 'content': 'Hello', 'size': 10, 'time': '2023-07-13 11:36:40', 'state': 'unread'}

        */
        if (recv.is_full_with_one_more_email(size)) {
            return false
        }
        let email = HashMap<String, Any>()
        email.add('sender', this.addr)
        email.add('receiver', recv.addr)
        email.add('content', content)
        email.add('size', size)
        email.add('time', DateTime.now().toString())
        email.add('state', 'unread')
        recv.inbox.add(email)
        return true
    }

    public func fetch(): HashMap<String, Any> {
        /*
        Retrieves the first unread email in the email box and marks it as read.
        :return: The first unread email in the email box, HashMap<String, Any>
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('sender', 'sender@example.com'), ('receiver', 'receiver@example.com'), ('content', 'Hello'), ('size', 10), ('time', '2023-07-13 11:36:40'), ('state', 'unread')])])
        >>> receiver.fetch()
        {'sender': 'sender@example.com', 'receiver': 'receiver@example.com', 'content': 'Hello', 'size': 10, 'time': '2023-07-13 11:36:40', 'state': 'read'}

        */
        for (i in 0..=this.inbox.size - 1) {
            let email = this.inbox[i]
            if (email.get('state').getOrThrow() as String == 'unread') {
                email.add('state', 'read')
                return email
            }
        }
        // Return an empty email if no unread email is found
        return HashMap<String, Any>()
    }

    public func is_full_with_one_more_email(size: Int64): Bool {
        /*
        Determines whether the email box is full after adding an email of the given size.
        :param size: The size of the email, Int64.
        :return: true if the email box is full, false otherwise.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.is_full_with_one_more_email(10)
        false

        */
        let totalSize = this.get_occupied_size() + size
        return totalSize > this.capacity
    }

    public func get_occupied_size(): Int64 {
        /*
        Gets the total size of the emails in the email box.
        :return: The total size of the emails in the email box, Int64.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> sender.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('sender', 'sender@example.com'), ('receiver', 'receiver@example.com'), ('content', 'Hello'), ('size', 10), ('time', DateTime.now()), ('state', 'unread')])])
        >>> sender.get_occupied_size()
        10

        */
        var totalSize: Int64 = 0
        for (email in this.inbox) {
            let size = email.get('size').getOrThrow() as Int64
            totalSize += size
        }
        return totalSize
    }

    public func clear_inbox(size: Int64): Unit {
        /*
        Clears the email box by deleting the oldest emails until the email box has enough space to accommodate the given size.
        :param size: The size of the email, Int64.
        >>> sender = EmailClient('sender@example.com', 100)
        >>> receiver = EmailClient('receiver@example.com', 50)
        >>> receiver.inbox = ArrayList<HashMap<String, Any>>([HashMap<String, Any>([('size', 10)]), HashMap<String, Any>([('size', 20)]), HashMap<String, Any>([('size', 15)])])
        >>> receiver.clear_inbox(30)
        >>> receiver.inbox
        [{'size': 15}]

        */
        let requiredSpace = size
        var currentOccupied = this.get_occupied_size()

        // Keep removing the oldest emails until there's enough space
        while (this.inbox.size > 0 && currentOccupied >= requiredSpace) {
            let oldestEmail = this.inbox[0]
            let oldestEmailSize = oldestEmail.get('size').getOrThrow() as Int64
            this.inbox.removeAt(0)
            currentOccupied -= oldestEmailSize
        }
    }
}

import std.collection.ArrayList

class EncryptionUtils {

    /*
    This is a class that provides methods for encryption, including the Caesar cipher, Vigenere cipher, and Rail Fence cipher.
    */

    let key: String

    public init(key: String) {
        /*
        Initializes the class with a key.
        :param key: The key to use for encryption, String.
        */
        this.key = key
    }

    public func caesar_cipher(plaintext: String, shift: Int64): String {
        /*
        Encrypts the plaintext using the Caesar cipher.
        :param plaintext: The plaintext to encrypt, String.
        :param shift: The number of characters to shift each character in the plaintext, Int64.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.caesar_cipher("abc", 1)
        'bcd'

        */
        var result = ""
        for (ch in plaintext) {
            if (ch >= 'a' && ch <= 'z') {
                let shifted = ((ch.toInt() - 'a'.toInt() + shift) % 26 + 26) % 26
                result += String.fromCharCode('a'.toInt() + shifted)
            } else if (ch >= 'A' && ch <= 'Z') {
                let shifted = ((ch.toInt() - 'A'.toInt() + shift) % 26 + 26) % 26
                result += String.fromCharCode('A'.toInt() + shifted)
            } else {
                result += ch
            }
        }
        return result
    }

    public func vigenere_cipher(plain_text: String): String {
        /*
        Encrypts the plaintext using the Vigenere cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.vigenere_cipher("abc")
        'kfa'

        */
        if (this.key.length == 0) {
            return plain_text
        }

        var result = ""
        var keyIndex = 0

        for (ch in plain_text) {
            if (ch >= 'a' && ch <= 'z') {
                let plainOffset = ch.toInt() - 'a'.toInt()
                let keyChar = this.key[keyIndex % this.key.length]
                let keyOffset = keyChar.toLowerCase()[0].toInt() - 'a'.toInt()
                let encryptedOffset = (plainOffset + keyOffset) % 26
                result += String.fromCharCode('a'.toInt() + encryptedOffset)
                keyIndex += 1
            } else if (ch >= 'A' && ch <= 'Z') {
                let plainOffset = ch.toInt() - 'A'.toInt()
                let keyChar = this.key[keyIndex % this.key.length]
                let keyOffset = keyChar.toLowerCase()[0].toInt() - 'a'.toInt()
                let encryptedOffset = (plainOffset + keyOffset) % 26
                result += String.fromCharCode('A'.toInt() + encryptedOffset)
                keyIndex += 1
            } else {
                result += ch
            }
        }
        return result
    }

    public func rail_fence_cipher(plain_text: String, rails: Int64): String {
        /*
        Encrypts the plaintext using the Rail Fence cipher.
        :param plaintext: The plaintext to encrypt, String.
        :return: The ciphertext, String.
        >>> e = EncryptionUtils("key")
        >>> e.rail_fence_cipher("abc", 2)
        'acb'

        */
        if (rails <= 1 || plain_text.length <= rails) {
            return plain_text
        }

        var result = ""
        var fence: ArrayList<ArrayList<String>> = ArrayList<ArrayList<String>>()

        // Initialize the fence with empty ArrayLists
        for (i in 0 ..< rails) {
            fence.add(ArrayList<String>())
        }

        var rail = 0
        var direction = 1

        for (ch in plain_text) {
            fence[rail].add(ch.toString())

            if (rail == 0) {
                direction = 1
            } else if (rail == rails - 1) {
                direction = -1
            }

            rail += direction
        }

        for (r in 0 ..< rails) {
            for (element in fence[r]) {
                result += element
            }
        }

        return result
    }
}

import std.math.numeric.Decimal
import std.regex.Regex
import std.collection.ArrayList

class ExpressionCalculator {

    /*
    This is a class in Cangjie that can perform calculations with basic arithmetic operations, including addition, subtraction, multiplication, division, and modulo.
    */

    let postfix_stack: ArrayList<String>
    let operat_priority: ArrayList<Int64>

    public init() {
        /*
        Initialize the expression calculator
        */
        postfix_stack = ArrayList<String>()
        operat_priority = ArrayList<Int64>([0, 3, 2, 1, -1, 1, 0, 2])
    }

    public func calculate(expression: String): Float64 {
        /*
        Calculate the result of the given postfix expression
        :param expression: String, the postfix expression to be calculated
        :return: Float64, the calculated result
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.calculate("2 + 3 * 4")
        14.0

        */
        prepare(expression)
        var stack: ArrayList<Decimal> = ArrayList<Decimal>()

        for token in postfix_stack {
            if !ExpressionCalculator.is_operator(token) {
                stack.add(Decimal.fromString(token).getOrThrow())
            } else {
                var second_value = stack.removeAt(stack.size() - 1)
                var first_value = stack.removeAt(stack.size() - 1)
                var result = ExpressionCalculator._calculate(first_value, second_value, token)
                stack.add(result)
            }
        }

        return stack.get(0).getOrThrow().toFloat64()
    }

    public func prepare(expression: String): Unit {
        /*
        Prepare the infix expression for conversion to postfix notation
        :param expression: String, the infix expression to be prepared
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.prepare("2+3*4")

        expression_calculator.postfix_stack = ['2', '3', '4', '*', '+']
        */
        postfix_stack.clear()
        var tokens = ExpressionCalculator.transform(expression).split("")
        var operator_stack: ArrayList<String> = ArrayList<String>()
        var current_number = ""

        for i in 0..tokens.size() {
            var token = tokens.getOrThrow(i)

            if token == " " {
                continue
            }

            if !ExpressionCalculator.is_operator(token) {
                current_number = current_number + token
            } else {
                if current_number != "" {
                    postfix_stack.add(current_number)
                    current_number = ""
                }

                if token == "(" {
                    operator_stack.add(token)
                } else if token == ")" {
                    while operator_stack.size() > 0 && operator_stack.get(operator_stack.size() - 1).getOrThrow() != "(" {
                        postfix_stack.add(operator_stack.removeAt(operator_stack.size() - 1))
                    }
                    operator_stack.removeAt(operator_stack.size() - 1) // Remove the '('
                } else {
                    while operator_stack.size() > 0 && 
                          operator_stack.get(operator_stack.size() - 1).getOrThrow() != "(" &&
                          compare(token, operator_stack.get(operator_stack.size() - 1).getOrThrow()) {
                        postfix_stack.add(operator_stack.removeAt(operator_stack.size() - 1))
                    }
                    operator_stack.add(token)
                }
            }
        }

        if current_number != "" {
            postfix_stack.add(current_number)
        }

        while operator_stack.size() > 0 {
            postfix_stack.add(operator_stack.removeAt(operator_stack.size() - 1))
        }
    }

    public static func is_operator(c: String): Bool {
        /*
        Check if a character is an operator in ['+', '-', '*', '/', '(', ')', '%']
        :param c: String, the character to be checked
        :return: Bool, true if the character is an operator, false otherwise
        >>> ExpressionCalculator.is_operator("+")
        true

        */
        return c == "+" || c == "-" || c == "*" || c == "/" || c == "(" || c == ")" || c == "%"
    }

    public func compare(cur: String, peek: String): Bool {
        /*
        Compare the precedence of two operators
        :param cur: String, the current operator
        :param peek: String, the operator at the top of the operator stack
        :return: Bool, true if the current operator has higher or equal precedence, false otherwise
        >>> expression_calculator = ExpressionCalculator()
        >>> expression_calculator.compare("+", "-")
        true

        */
        var current_priority = get_priority(cur)
        var peek_priority = get_priority(peek)
        return peek_priority >= current_priority
    }

    private func get_priority(op: String): Int64 {
        if op == "+" {
            return operat_priority.get(1).getOrThrow()
        } else if op == "-" {
            return operat_priority.get(2).getOrThrow()
        } else if op == "*" {
            return operat_priority.get(3).getOrThrow()
        } else if op == "/" {
            return operat_priority.get(7).getOrThrow()
        } else if op == "%" {
            return operat_priority.get(5).getOrThrow()
        } else if op == "(" {
            return operat_priority.get(4).getOrThrow()
        } else if op == ")" {
            return operat_priority.get(6).getOrThrow()
        }
        return 0
    }

    public static func _calculate(first_value: Decimal, second_value: Decimal, current_op: String): Decimal {
        /*
        Perform the mathematical calculation based on the given operands and operator
        :param first_value: Decimal, the first operand
        :param second_value: Decimal, the second operand
        :param current_op: String, the operator
        :return: Decimal, the calculated result
        >>> ExpressionCalculator._calculate("2", "3", "+")
        5.0

        */
        if current_op == "+" {
            return first_value + second_value
        } else if current_op == "-" {
            return first_value - second_value
        } else if current_op == "*" {
            return first_value * second_value
        } else if current_op == "/" {
            if second_value.isZero() {
                panic("Division by zero")
            }
            return first_value / second_value
        } else if current_op == "%" {
            if second_value.isZero() {
                panic("Modulo by zero")
            }
            return first_value % second_value
        }
        return first_value
    }

    public static func transform(expression: String): String {
        /*
        Transform the infix expression to a format suitable for conversion
        :param expression: String, the infix expression to be transformed
        :return: String, the transformed expression
        >>> ExpressionCalculator.transform("2 + 3 * 4")
        "2+3*4"

        */
        var result = ""
        for char in expression {
            if char != " " {
                result = result + char
            }
        }
        return result
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs

class FitnessTracker {

    /*
    This is a class as fitness tracker that implements to calculate BMI (Body Mass Index) and calorie intake based on the user's height, weight, age, and sex.
    */

    let height: Float64
    let weight: Float64
    let age: Int64
    let sex: String
    let BMI_std: ArrayList<HashMap<String, ArrayList<Int64>>>

    public init(height: Float64, weight: Float64, age: Int64, sex: String) {
        /*
        Initialize the class with height, weight, age, and sex, and calculate the BMI standard based on sex, and male is 20-25, female is 19-24.
        */
        this.height = height
        this.weight = weight
        this.age = age
        this.sex = sex
        this.BMI_std = ArrayList<HashMap<String, ArrayList<Int64>>>()
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("male", ArrayList<Int64>([20, 25]))]))
        this.BMI_std.add(HashMap<String, ArrayList<Int64>>([("female", ArrayList<Int64>([19, 24]))]))
    }

    public func get_BMI(): Float64 {
        /*
        Calculate the BMI based on the height and weight.
        :return: BMI,which is the weight divide by the square of height, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.get_BMI()
        21.604938271604937

        */
        return this.weight / (this.height * this.height)
    }

    public func condition_judge(): Int64 {
        /*
        Judge the condition of the user based on the BMI standard.
        :return: 1 if the user is too fat, -1 if the user is too thin, 0 if the user is normal, Int64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.condition_judge()
        -1

        */
        let bmi = this.get_BMI()
        let standard = this.get_standard()
        let min_bmi = Float64(standard.get(0).getOrThrow())
        let max_bmi = Float64(standard.get(1).getOrThrow())

        if bmi < min_bmi {
            return -1
        } else if bmi > max_bmi {
            return 1
        } else {
            return 0
        }
    }

    private func get_standard(): ArrayList<Int64> {
        for item in this.BMI_std {
            if item.contains(this.sex) {
                return item.get(this.sex).getOrThrow()
            }
        }
        // Default to male standard if sex not found
        return this.BMI_std.get(0).get("male").getOrThrow()
    }

    public func calculate_calorie_intake(): Float64 {
        /*
        Calculate the calorie intake based on the user's condition and BMR (Basal Metabolic Rate),BMR is calculated based on the user's height, weight, age, and sex,male is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5),female is Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161), and the calorie intake is calculated based on the BMR and the user's condition,if the user is too fat, the calorie intake is BMR * 1.2, if the user is too thin, the calorie intake is BMR * 1.6, if the user is normal, the calorie intake is BMR * 1.4.
        :return: calorie intake, Float64.
        >>> fitnessTracker = FitnessTracker(1.8, 70.0, 20, "male")
        >>> fitnessTracker.calculate_calorie_intake()
        986.0

        */
        let bmr = this.calculate_bmr()
        let condition = this.condition_judge()

        if condition == 1 { // too fat
            return bmr * 1.2
        } else if condition == -1 { // too thin
            return bmr * 1.6
        } else { // normal
            return bmr * 1.4
        }
    }

    private func calculate_bmr(): Float64 {
        if this.sex == "male" {
            return Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) + Float64(5)
        } else { // female
            return Float64(10) * this.weight + 6.25 * this.height - Float64(5) * Float64(this.age) - Float64(161)
        }
    }
}

import std.collection.ArrayList

class GomokuGame {

    /*
    This class is an implementation of a Gomoku game, supporting for making moves, checking for a winner, and checking if there are five consecutive symbols on the game board.
    */

    let board_size: Int64
    let board: ArrayList<ArrayList<String>>
    var current_player: String

    public init(board_size: Int64) {
        /*
        Initializes the game with a given board size.
        It initializes the board with empty spaces and sets the current player symbol as 'X'.
        */
        this.board_size = board_size
        this.board = ArrayList<ArrayList<String>>()
        this.current_player = "X"
        for (_ in 0..board_size) {
            let row: ArrayList<String> = ArrayList<String>()
            for (_ in 0..board_size) {
                row.add(" ")
            }
            board.add(row)
        }
    }

    public func make_move(row: Int64, col: Int64): Bool {
        /*
        Makes a move at the given row and column.
        If the move is valid, it places the current player's symbol on the board
        and changes the current player to the other player (if the current player is 'X', then it becomes 'O' and vice versa).
        :param row: Int64, the row index of this move
        :param col: Int64, the column index
        return: true if the move is valid, or false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> gomokuGame.make_move(5, 5)
        true
        >>> gomokuGame.make_move(5, 5)
        false
        */
        if (row < 0 || row >= board_size || col < 0 || col >= board_size) {
            return false
        }
        if (board[row][col] != " ") {
            return false
        }
        board[row][col] = current_player
        if (current_player == "X") {
            current_player = "O"
        } else {
            current_player = "X"
        }
        return true
    }

    public func check_winner(): Option<String> {
        /*
        Checks if there is a winner by looking for five in a row in all directions (horizontal, vertical, diagonal).
        return: the symbol of the winning player (either 'X' or 'O') if there is a winner, or None otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame.check_winner()
        'X'
        */
        for (row in 0..board_size) {
            for (col in 0..board_size) {
                let cell_value = board[row][col]
                if (cell_value != " ") {
                    // Check all 4 directions: horizontal, vertical, diagonal down-right, diagonal up-right
                    let directions: ArrayList<(Int64, Int64)> = ArrayList<(Int64, Int64)>()
                    directions.add((1, 0))  // horizontal
                    directions.add((0, 1))  // vertical
                    directions.add((1, 1))  // diagonal down-right
                    directions.add((1, -1)) // diagonal up-right

                    for (dir in directions) {
                        if (_check_five_in_a_row(row, col, dir)) {
                            return Some(cell_value)
                        }
                    }
                }
            }
        }
        return None<String>
    }

    public func _check_five_in_a_row(row: Int64, col: Int64, direction: (Int64, Int64)): Bool {
        /*
        checks if there are five consecutive symbols of the same player in a row starting from a given cell in a given direction (horizontal, vertical, diagonal).
        Counts the number of consecutive symbols in that direction starting from the given cell,
        :param row: Int64, row of the given cell
        :param col: Int64, column of the given cell
        :param direction: tuple, (Int64, Int64), named as (dx, dy). Row and col will plus several dx and dy repectively.
        :return: true if there are five consecutive symbols of the same player, and false otherwise.
        >>> gomokuGame = GomokuGame(10)
        >>> moves = [(5, 5), (0, 0), (5, 4), (0, 1), (5, 3), (0, 2), (5, 2), (0, 3), (5, 1)]
        >>> for (move in moves) {
        ...     gomokuGame.make_move(move[0], move[1])
        ... }
        >>> gomokuGame._check_five_in_a_row(5, 1, (0, 1))
        true
        >>> gomokuGame._check_five_in_a_row(5, 1, (1, 1))
        false
        */
        let dx = direction.0
        let dy = direction.1
        let player = board[row][col]

        // Count in the forward direction
        var count = 1
        var r = row + dx
        var c = col + dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == player) {
            count++
            r += dx
            c += dy
        }

        // Count in the backward direction
        r = row - dx
        c = col - dy
        while (r >= 0 && r < board_size && c >= 0 && c < board_size && board[r][c] == player) {
            count++
            r -= dx
            c -= dy
        }

        return count >= 5
    }
}

import std.collection.HashMap

class Hotel {

    /*
    This is a class as hotel management system, managing the booking, check-in, check-out, and availability of rooms in a hotel with different room types.
    */

    let name: String
    let available_rooms: HashMap<String, Int64>
    var booked_rooms: HashMap<String, HashMap<String, Int64>>

    public init(name: String, rooms: HashMap<String, Int64>) {
        /*
        Initialize the three fields in Hotel System.
        name is the hotel name.
        available_rooms stores the remaining rooms in the hotel
        booked_rooms stores the rooms that have been booked and the person's name who booked rooms.
        >>> hotel.name
        'peace hotel'
        >>> hotel.available_rooms
        available_rooms = {'single': 5, 'double': 3}
        >>> hotel.booked_rooms
        {'single': {'guest 1': 2, 'guest 2':1}, 'double': {'guest1': 1}}
        */
        this.name = name
        this.available_rooms = HashMap<String, Int64>(rooms)
        this.booked_rooms = HashMap<String, HashMap<String, Int64>>()
    }

    public func book_room(room_type: String, room_number: Int64, name: String): String {
        /*
        Check if there are any rooms of the specified type available.
        if rooms are adequate, modify available_rooms and booked_rooms and finish booking, or fail to book otherwise.
        :param room_type: String
        :param room_number: Int64, the expected number of specified type rooms to be booked
        :param name: String, guest name
        :return: if number of rooms about to be booked doesn't exceed the remaining rooms, return str 'Success!'
                if exceeds but quantity of available rooms is not equal to zero, return Int64.toString() (the remaining quantity of this room type).
                if exceeds and quantity is zero or the room_type isn't in available_room, return 'false'.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 5, 'guest 1')
        '4'
        >>> hotel.book_room('single', 4, 'guest 1')
        'Success!'
        >>> hotel.book_room('single', 1, 'guest 1')
        'false'
        >>> hotel.book_room('triple', 1, 'guest 1')
        'false'
        */
        var available_count = this.available_rooms.get(room_type)
        if (available_count == none) {
            return "false"
        }

        var count = available_count.getOrThrow()
        if (count >= room_number) {
            // Enough rooms available, proceed with booking
            this.available_rooms.add(room_type, count - room_number)

            // Update booked_rooms
            var guest_map = this.booked_rooms.get(room_type)
            if (guest_map == none) {
                guest_map = HashMap<String, Int64>()
            }
            var current_booked = guest_map.getOrThrow().get(name)
            if (current_booked == none) {
                guest_map.getOrThrow().add(name, room_number)
            } else {
                var new_count = current_booked.getOrThrow() + room_number
                guest_map.getOrThrow().add(name, new_count)
            }
            this.booked_rooms.add(room_type, guest_map.getOrThrow())
            return "Success!"
        } else if (count > 0) {
            // Some rooms available but not enough
            return count.toString()
        } else {
            // No rooms available
            return "false"
        }
    }

    public func check_in(room_type: String, room_number: Int64, name: String): Bool {
        /*
        Check if the room of the specified type and number is booked by the person named name.
        Remove this name when check in successfuly(room_number is equal to specific person's booked_rooms. When the actual check in quantity (room_number) is less than the booked quantity, number in booked_rooms will be booked quantity minus actual quantity
        :param room_type: String, check in room type
        :param room_number: Int64, check in room number
        :param name: String, person name
        :return false: only if the room_type is not in the booked_rooms or room_number is higher than quantity in booked rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.book_room('single', 1, 'guest 1')
        true
        >>> hotel.check_in('single', 2, 'guest 1')
        false
        >>> hotel.check_in('single', 1, 'guest 1')
        true
        >>> hotel.booked_rooms
        {'single': {}}
        */
        var room_map = this.booked_rooms.get(room_type)
        if (room_map == none) {
            return false
        }

        var guest_map = room_map.getOrThrow()
        var booked_count = guest_map.get(name)
        if (booked_count == none) {
            return false
        }

        var count = booked_count.getOrThrow()
        if (room_number > count) {
            return false
        }

        if (room_number == count) {
            // Guest is checking in all their booked rooms, remove them
            guest_map.remove(name)
        } else {
            // Guest is checking in only part of their booked rooms, update count
            guest_map.add(name, count - room_number)
        }

        // Update the booked_rooms map
        this.booked_rooms.add(room_type, guest_map)
        return true
    }

    public func check_out(room_type: String, room_number: Int64): Unit {
        /*
        Check out rooms, add number for specific type in available_rooms.
        If room_type is new, add new type in available_rooms.
        :param room_type: String, check out room type
        :param room_number: Int64, check out room number
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.check_out('single', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3}
        >>> hotel.check_out('triple', 2)
        >>> hotel.available_rooms
        {'single': 7, 'double': 3, 'triple': 2}
        */
        var current_count = this.available_rooms.get(room_type)
        if (current_count == none) {
            this.available_rooms.add(room_type, room_number)
        } else {
            var new_count = current_count.getOrThrow() + room_number
            this.available_rooms.add(room_type, new_count)
        }
    }

    public func get_available_rooms(room_type: String): Int64 {
        /*
        Get the number of specific type of available rooms.
        :param room_type: String, the room type that want to know
        :return: Int64, the remaining number of this type rooms.
        >>> hotel = Hotel('peace hotel', HashMap<String, Int64>([('single', 5), ('double', 3)]))
        >>> hotel.get_available_rooms('single')
        5
        */
        var count = this.available_rooms.get(room_type)
        if (count == none) {
            return 0
        }
        return count.getOrThrow()
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Employee <: Equatable<Employee> {

    /*
    This is a class representing an employee with attributes such as name, position, department, and salary.
    */

    var name: String
    var position: String
    var department: String
    var salary: Int64

    public init(name: String, position: String, department: String, salary: Int64) {
        /*
        Initialize an Employee with name, position, department, and salary.
        :param name: The employee's name, String.
        :param position: The employee's position, String.
        :param department: The employee's department, String.
        :param salary: The employee's salary, Int64.
        */
        this.name = name
        this.position = position
        this.department = department
        this.salary = salary
    }

    public override operator func != (that: Employee): Bool {
        /*
        Check if two Employee objects are not equal.
        :param that: Another Employee object to compare with.
        :return: true if any attribute is different, false otherwise.
        */
        return this.name != that.name || this.position != that.position || this.department != that.department || this.salary != that.salary
    }

    public override operator func == (that: Employee): Bool {
        /*
        Check if two Employee objects are equal.
        :param that: Another Employee object to compare with.
        :return: true if all attributes are the same, false otherwise.
        */
        return this.name == that.name && this.position == that.position && this.department == that.department && this.salary == that.salary
    }
}

class HRManagementSystem {

    /*
    This is a class as personnel management system that implements functions such as adding, deleting, querying, and updating employees
    */

    var employees: HashMap<Int64, Employee>

    public init() {
        /*
        Initialize the HRManagementSystem withan attribute employees, which is an empty dictionary.
        */
        this.employees = HashMap<Int64, Employee>()
    }

    public func add_employee(employee_id: Int64, name: String, position: String, department: String, salary: Int64): Bool {
        /*
        Add a new employee to the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :param name: The employee's name, String.
        :param position: The employee's position, String.
        :param department: The employee's department, String.
        :param salary: The employee's salary, Int64.
        :return: If the employee is already in the HRManagementSystem, returns false, otherwise, returns true.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.add_employee(1, 'John', 'Manager', 'Sales', 100000)
        true
        >>> hrManagementSystem.add_employee(1, 'John', 'Manager', 'Sales', 100000)
        false

        */
        if (this.employees.contains(employee_id)) {
            return false
        }
        var employee = Employee(name, position, department, salary)
        this.employees.add(employee_id, employee)
        return true
    }

    public func remove_employee(employee_id: Int64): Bool {
        /*
        Remove an employee from the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :return: If the employee is already in the HRManagementSystem, returns true, otherwise, returns false.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.remove_employee(1)
        true
        >>> hrManagementSystem.remove_employee(2)
        false

        */
        if (this.employees.contains(employee_id)) {
            this.employees.remove(employee_id)
            return true
        }
        return false
    }

    public func update_employee(employee_id: Int64, employee_info: HashMap<String, Any>): Bool {
        /*
        Update an employee's information in the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :param employee_info: The employee's information, HashMap<String, Any>.
        :return: If the employee is already in the HRManagementSystem, returns true, otherwise, returns false.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.update_employee(1, HashMap<String, Any>([('name', 'John Doe'), ('position', 'Manager'), ('department', 'Sales'), ('salary', 20000)]))
        true
        >>> hrManagementSystem.update_employee(2, HashMap<String, Any>([('name', 'John Doe'), ('position', 'Manager'), ('department', 'Sales'), ('salary', 20000)]))
        false

        */
        if (this.employees.contains(employee_id)) {
            var employee = this.employees[employee_id]
            if (employee_info.contains("name")) {
                employee.name = employee_info["name"] as String
            }
            if (employee_info.contains("position")) {
                employee.position = employee_info["position"] as String
            }
            if (employee_info.contains("department")) {
                employee.department = employee_info["department"] as String
            }
            if (employee_info.contains("salary")) {
                employee.salary = employee_info["salary"] as Int64
            }
            return true
        }
        return false
    }

    public func get_employee(employee_id: Int64): Option<Employee> {
        /*
        Get an employee's information from the HRManagementSystem.
        :param employee_id: The employee's id, Int64.
        :return: If the employee is already in the HRManagementSystem, returns the employee's information, otherwise, returns None.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees.add(1, Employee('John', 'Manager', 'Sales', 100000))
        >>> hrManagementSystem.get_employee(1)
        Employee('John', 'Manager', 'Sales', 100000)
        >>> hrManagementSystem.get_employee(2)
        None

        */
        if (this.employees.contains(employee_id)) {
            return Some(this.employees[employee_id])
        }
        return None
    }

    public func list_employees(): ArrayList<Employee> {
        /*
        List all employees' information in the HRManagementSystem.
        :return: A list of all employees' information, ArrayList<Employee>.
        >>> hrManagementSystem = HRManagementSystem()
        >>> hrManagementSystem.employees = HashMap<Int64, Employee>([(1, Employee('John', 'Manager', 'Sales', 100000))])
        >>> hrManagementSystem.list_employees()
        ArrayList<Employee>([Employee('John', 'Manager', 'Sales', 100000)])

        */
        var result = ArrayList<Employee>()
        for ((id, employee) in this.employees) {
            result.add(employee)
        }
        return result
    }
}

import std.collection.ArrayList

class Interpolation {

    /*
    This is a class that implements the Linear interpolation operation of one-dimensional and two-dimensional data
    */

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of one-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The y-coordinate of the interpolation point, ArrayList<Float64>.
        >>> Interpolation.interpolate_1d(ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([1.5, 2.5]))
        [1.5, 2.5]

        */
        var result = ArrayList<Float64>()

        for i in 0..<x_interp.size {
            let x_val = x_interp[i]

            // Find the interval that contains x_val
            var idx = 0
            for j in 0..<x.size {
                if x[j] >= x_val {
                    if j == 0 {
                        idx = 0
                    } else {
                        idx = j - 1
                    }
                    break
                }
                if j == x.size - 1 {
                    idx = j - 1
                }
            }

            // Ensure idx is within bounds
            if idx < 0 {
                idx = 0
            }
            if idx >= x.size - 1 {
                idx = x.size - 2
            }

            let x0 = x[idx]
            let x1 = x[idx + 1]
            let y0 = y[idx]
            let y1 = y[idx + 1]

            // Perform linear interpolation
            var y_interp_val: Float64
            if x1 == x0 {
                y_interp_val = y0
            } else {
                y_interp_val = y0 + (y1 - y0) * (x_val - x0) / (x1 - x0)
            }

            result.add(y_interp_val)
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        /*
        Linear interpolation of two-dimensional data
        :param x: The x-coordinate of the data point, ArrayList<Float64>.
        :param y: The y-coordinate of the data point, ArrayList<Float64>.
        :param z: The z-coordinate of the data point, ArrayList<ArrayList<Float64>>.
        :param x_interp: The x-coordinate of the interpolation point, ArrayList<Float64>.
        :param y_interp: The y-coordinate of the interpolation point, ArrayList<Float64>.
        :return: The z-coordinate of the interpolation point, ArrayList<Float64>.
        >>> let x = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let y = ArrayList<Float64>([1.0, 2.0, 3.0])
        >>> let z = ArrayList<ArrayList<Float64>>([ArrayList<Float64>([1.0, 2.0, 3.0]), ArrayList<Float64>([4.0, 5.0, 6.0]), ArrayList<Float64>([7.0, 8.0, 9.0])])
        >>> let x_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let y_interp = ArrayList<Float64>([1.5, 2.5])
        >>> let result = Interpolation.interpolate_2d(x, y, z, x_interp, y_interp)
        >>> result
        [3.0, 7.0]

        */
        var result = ArrayList<Float64>()

        for i in 0..<x_interp.size {
            let x_val = x_interp[i]
            let y_val = y_interp[i]

            // Find the x indices
            var x_idx = 0
            for j in 0..<x.size {
                if x[j] >= x_val {
                    if j == 0 {
                        x_idx = 0
                    } else {
                        x_idx = j - 1
                    }
                    break
                }
                if j == x.size - 1 {
                    x_idx = j - 1
                }
            }

            // Find the y indices
            var y_idx = 0
            for j in 0..<y.size {
                if y[j] >= y_val {
                    if j == 0 {
                        y_idx = 0
                    } else {
                        y_idx = j - 1
                    }
                    break
                }
                if j == y.size - 1 {
                    y_idx = j - 1
                }
            }

            // Ensure indices are within bounds
            if x_idx < 0 {
                x_idx = 0
            }
            if x_idx >= x.size - 1 {
                x_idx = x.size - 2
            }

            if y_idx < 0 {
                y_idx = 0
            }
            if y_idx >= y.size - 1 {
                y_idx = y.size - 2
            }

            // Get the four surrounding points
            let x0 = x[x_idx]
            let x1 = x[x_idx + 1]
            let y0 = y[y_idx]
            let y1 = y[y_idx + 1]

            let z00 = z[y_idx][x_idx]
            let z01 = z[y_idx][x_idx + 1]
            let z10 = z[y_idx + 1][x_idx]
            let z11 = z[y_idx + 1][x_idx + 1]

            // Perform bilinear interpolation
            var z_interp_val: Float64
            if x1 == x0 && y1 == y0 {
                z_interp_val = z00
            } else if x1 == x0 {
                z_interp_val = z00 + (z10 - z00) * (y_val - y0) / (y1 - y0)
            } else if y1 == y0 {
                z_interp_val = z00 + (z01 - z00) * (x_val - x0) / (x1 - x0)
            } else {
                let f_x0 = z00 + (z01 - z00) * (x_val - x0) / (x1 - x0)
                let f_x1 = z10 + (z11 - z10) * (x_val - x0) / (x1 - x0)
                z_interp_val = f_x0 + (f_x1 - f_x0) * (y_val - y0) / (y1 - y0)
            }

            result.add(z_interp_val)
        }

        return result
    }
}

import std.convert.Parsable
import std.convert.Formattable
import std.collection.ArrayList

class IPAddress {

    /*
    This is a class to process IP Address, including validating, getting the octets and obtaining the binary representation of a valid IP address.
    */

    let ip_address: String

    public init(ip_address: String) {
        /*
        Initialize the IP address to the specified address
        :param ip_address:String
        */
        this.ip_address = ip_address
    }

    public func is_valid(): Bool {
        /*
        Judge whether the IP address is valid, that is, whether the IP address is composed of four Decimal digits separated by '.'. Each digit is greater than or equal to 0 and less than or equal to 255
        :return: Bool
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.is_valid()
        true
        */
        var parts = this.ip_address.split(".")
        if (parts.size != 4) {
            return false
        }

        for (i in 0..4) {
            var part_opt = parts.get(i)
            if (!part_opt.hasValue()) {
                return false
            }
            var part = part_opt.getOrThrow()

            // Check if part is empty
            if (part.length == 0) {
                return false
            }

            // Check if all characters are digits
            for (j in 0..part.length) {
                var rune = part[j]
                if (rune < '0' || rune > '9') {
                    return false
                }
            }

            // Convert to integer
            var num_opt = Int64.parse(part)
            if (!num_opt.hasValue()) {
                return false
            }
            var num = num_opt.getOrThrow()

            // Check range [0, 255]
            if (num < 0 || num > 255) {
                return false
            }

            // Check for leading zeros (except for "0" itself)
            if (part.length > 1 && part[0] == '0') {
                return false
            }
        }

        return true
    }

    public func get_octets(): ArrayList<String> {
        /*
        If the IP address is valid, the list of four decimal numbers separated by "." constituting the IP address is returned; otherwise, an empty list is returned
        :return: ArrayList<String>
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_octets()
        ["10", "10", "10", "10"]
        */
        if (!this.is_valid()) {
            return ArrayList<String>()
        }

        var octets = ArrayList<String>()
        var parts = this.ip_address.split(".")

        for (i in 0..4) {
            var part_opt = parts.get(i)
            if (part_opt.hasValue()) {
                octets.add(part_opt.getOrThrow())
            }
        }

        return octets
    }

    public func get_binary(): String {
        /*
        If the IP address is valid, return the binary form of the IP address; otherwise, return ''
        :return: String
        >>> ipaddress = IPAddress("10.10.10.10")
        >>> ipaddress.get_binary()
        "00001010.00001010.00001010.00001010"
        */
        if (!this.is_valid()) {
            return ""
        }

        var result = ""
        var parts = this.ip_address.split(".")

        for (i in 0..parts.size) {
            var part_opt = parts.get(i)
            if (part_opt.hasValue()) {
                var part = part_opt.getOrThrow()
                var num_opt = Int64.parse(part)
                if (num_opt.hasValue()) {
                    var num = num_opt.getOrThrow()
                    var binary = ""

                    // Convert to 8-bit binary
                    for (j in 0..8) {
                        if ((num >> (7 - j)) & 1 == 1) {
                            binary += "1"
                        } else {
                            binary += "0"
                        }
                    }

                    if (i > 0) {
                        result += "." + binary
                    } else {
                        result += binary
                    }
                }
            }
        }

        return result
    }
}

import std.net.IPAddress
import std.posix.gethostname
import std.regex.*

class IpUtil {

    /*
    This is a class as tool for ip that can be used to obtain the local IP address, validate its validity, and also provides the functionality to retrieve the corresponding hostname.
    */

    public static func is_valid_ipv4(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv4 address.
        :param ip_address: String, the IP address to check
        :return: Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv4('192.168.0.123')
        true
        >>> IpUtil.is_valid_ipv4('256.0.0.0')
        false

        */
        let ipv4Pattern = Regex(#"^((25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)\.){3}(25[0-5]|2[0-4][0-9]|[01]?[0-9][0-9]?)$"#)
        let match = ipv4Pattern.find(ip_address)
        return match.isSome()
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        /*
        Check if the given IP address is a valid IPv6 address.
        :param ip_address:String, the IP address to check
        :return:Bool, true if the IP address is valid, false otherwise
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:0000:0000:8a2e:0370:7334')
        true
        >>> IpUtil.is_valid_ipv6('2001:0db8:85a3:::8a2e:0370:7334')
        false

        */
        // IPv6 regex pattern to match standard IPv6 formats
        let ipv6Pattern = Regex(#"^([0-9a-fA-F]{1,4}:){7}[0-9a-fA-F]{1,4}$|^::1$|^::$|^([0-9a-fA-F]{1,4}:)*::([0-9a-fA-F]{1,4}:)*[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:)*::$|^::([0-9a-fA-F]{1,4}:)*[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:){1,7}:$|^:([0-9a-fA-F]{1,4}:){1,7}$|^([0-9a-fA-F]{1,4}:){1,6}::[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:){1,5}::([0-9a-fA-F]{1,4}:)?[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:){1,4}::([0-9a-fA-F]{1,4}:){0,2}[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:){1,3}::([0-9a-fA-F]{1,4}:){0,3}[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:){1,2}::([0-9a-fA-F]{1,4}:){0,4}[0-9a-fA-F]{1,4}$|^[0-9a-fA-F]{1,4}::([0-9a-fA-F]{1,4}:){0,5}[0-9a-fA-F]{1,4}$|^::([0-9a-fA-F]{1,4}:){0,6}[0-9a-fA-F]{1,4}$|^([0-9a-fA-F]{1,4}:){1,7}:$|^:([0-9a-fA-F]{1,4}:){0,7}$"#)
        let match = ipv6Pattern.find(ip_address)
        return match.isSome()
    }

    public static func get_hostname(ip_address: String): Option<String> {
        /*
        Get the hostname associated with the given IP address.
        :param ip_address:String, the IP address to get the hostname for
        :return: String, the hostname associated with the IP address
        >>> IpUtil.get_hostname('110.242.68.3')
        'www.baidu.com'
        >>> IpUtil.get_hostname('10.0.0.1')
        None

        */
        try {
            let ip = IPAddress.parse(ip_address)
            // Access the hostname property of the IP address
            return ip.hostName
        } catch {
            // If parsing fails, return None
            return None
        }
    }
}

